import type { Quiz, QuizQuestion } from '../types'

const phase6Question = (id: string, prompt: string, options: string[], correctAnswer: number, explanation: string, relatedLessonId: string, kind: QuizQuestion['kind'] = 'knowledge'): QuizQuestion => ({ id, prompt, options, correctAnswer, explanation, relatedLessonId, kind, difficulty: kind === 'calculation' ? 'advanced' : 'applied', objective: 'Apply the lesson evidence without treating practice as approval.', trainingData: { source: 'original', educationalOnly: true } })

const baseQuizzes: Quiz[] = [

  { id: 'hazardous-atmospheres', title: 'Explosive atmospheres and hazards', level: 'Beginner', description: 'Test your understanding of releases, ventilation, gas, vapour, mist, and dust.', lessonIds: ['ex001-foundations', 'hazardous-areas', 'gas-vapour-mist-dust'], questions: [
    { id: 'q-atmosphere-1', prompt: 'Under IEC 60079-10-1 and IEC 60079-10-2, which factors are primary inputs for hazardous area classification', options: ['Only the nominal operating voltage and power factor of nearby machinery', 'The structural steel building foundations and mechanical pipe support spacing', 'Flammable substance properties, sources and grades of release, and ventilation effectiveness', 'The acoustic noise emissions and thermal dissipation of nearby mechanical rotating equipment'], correctAnswer: 2, explanation: 'Hazardous area classification depends on substance characteristics (such as flash point, LEL, and auto-ignition temperature), grades of release, and ventilation degree and availability.', relatedLessonId: 'hazardous-areas' },
    { id: 'q-atmosphere-2', prompt: 'Why are combustible dust layers considered a primary explosion risk in hazardous areas', options: ['They continuously raise the minimum ignition energy required for dust clouds', 'They eliminate smouldering risks by forming an oxygen-tight crust over surfaces', 'They prevent electrical tracking across high-voltage terminal insulators', 'They thermally insulate hot surfaces and can be disturbed into explosive dust clouds'], correctAnswer: 3, explanation: 'Dust layers act as thermal insulation, causing surface temperatures to rise and potentially smoulder, and can be disturbed by shock or draughts into an explosive dust cloud.', relatedLessonId: 'gas-vapour-mist-dust' },
  ] },
  { id: 'zones-and-epl', title: 'Zones and EPL selection', level: 'Intermediate', description: 'Practise relating area information to equipment protection capability.', lessonIds: ['zones-and-epl', 'equipment-selection-marking'], questions: [
    { id: 'q-epl-1', prompt: 'What does an Equipment Protection Level (EPL) indicate under IEC 60079-0', options: ['The level of protection assigned to equipment based on its likelihood of becoming an ignition source in explosive gas or dust atmospheres', 'A complete site installation authorization that bypasses hazardous area zone matching', 'A certified log proving that equipment has undergone all required periodic inspections', 'A credential certifying the technical competence of the installation technician'], correctAnswer: 0, explanation: 'An Equipment Protection Level (EPL, such as Ga/Gb/Gc or Da/Db/Dc) defines the risk of the equipment becoming an ignition source under normal operation, expected malfunction, or rare malfunction.', relatedLessonId: 'zones-and-epl' },
    { id: 'q-epl-2', prompt: 'A drawing classifies an area as Zone 1 IIB T3. An inspector finds a motor marked Ex ec IIA T4 Gc. What is the correct procedure?', options: ['Energize the equipment since T4 (135°C) is safer than T3 (200°C) and the housing is clean', 'Hold acceptance, control the condition, and escalate the EPL (Gc vs Gb) and gas group (IIA vs IIB) mismatches for engineering verification', 'Remove the nameplate marking and commission under general industrial procedures because Ex ec is acceptable', 'Assume the equipment certificate automatically invalidates the area classification drawing because T4 is a better temperature class'], correctAnswer: 1, explanation: 'Despite the favourable T-class (T4 < T3), the equipment fails on both EPL (Gc is not permitted in Zone 1) and gas group (IIA cannot be used in IIB). Acceptance must be held and escalated.', relatedLessonId: 'equipment-selection-marking' },
  ] },
  { id: 'protection-concepts', title: 'Protection concepts', level: 'Intermediate', description: 'Review the intent and boundaries of Ex d, Ex e, Ex i, Ex t, and Ex p.', lessonIds: ['ex-d-ex-e', 'ex-i-ex-t-ex-p'], questions: [
    { id: 'q-protection-1', prompt: 'Which condition can compromise the explosion protection capability of an Ex d flameproof enclosure', options: ['Conducting an initial inspection in accordance with IEC 60079-17', 'Applying approved non-setting, non-metallic grease to machined joint surfaces', 'Exceeding maximum permitted flamepath gaps, using wrong fastener grades, or unapproved drilling', 'Fitting certified stopping plugs of matching thread form and property class'], correctAnswer: 2, explanation: 'Flameproof integrity depends on strict flamepath dimensions, fastener tensile strength to withstand explosion pressure, and certified entry integrity.', relatedLessonId: 'ex-d-ex-e' },
    { id: 'q-protection-2', prompt: 'What is fundamental when assessing an intrinsically safe (Ex i) installation under IEC 60079-14 and IEC 60079-25', options: ['Verifying that the external enclosure provides an ingress protection rating of at least IP66', 'Ensuring internal overpressure is monitored with a certified differential pressure sensor', 'Measuring flamepath joint clearances with calibrated non-metallic feeler gauges', 'Matching complete circuit entity parameters (Ui, Ii, Pi, Ci, Li) and cable characteristics'], correctAnswer: 3, explanation: 'Intrinsic safety is a system concept requiring verification that the energy-limiting apparatus, interconnecting cable, and field device satisfy combined electrical parameters.', relatedLessonId: 'ex-i-ex-t-ex-p' },
  ] },
  { id: 'installation-selection', title: 'Equipment selection and installation', level: 'Intermediate', description: 'Check marking, accessory, entry, bonding, and modification decisions.', lessonIds: ['equipment-selection-marking', 'installation-fundamentals'], questions: [
    { id: 'q-installation-1', prompt: 'Does a compliant equipment Ex certificate and nameplate marking alone confirm that an installation is safe to energize', options: ['No, complete installed conditions including cable glands, earthing, environmental limits, and IEC 60079-14 compliance must be verified', 'Yes, a certified nameplate guarantees complete installation integrity regardless of workmanship', 'Only if the certified apparatus was manufactured within the preceding twelve calendar months', 'Only when installed in Zone 2 or Zone 22 areas where explosive atmospheres are unlikely'], correctAnswer: 0, explanation: 'Certification proves that the apparatus meets manufacturing standards, but safe operation requires verifying complete installed conditions, cable glands, earthing, and IEC 60079-14 compliance.', relatedLessonId: 'equipment-selection-marking' },
    { id: 'q-installation-2', prompt: 'What is the required response when an undocumented physical modification is discovered on certified Ex equipment during an installation check', options: ['Accept the modification if the equipment has passed an insulation resistance test', 'Record the non-conformity, control the equipment status, and route through formal change evaluation', 'Conceal the altered component and commission the circuit if production is scheduled', 'Modify the equipment marking tag on site to match the as-found physical arrangement'], correctAnswer: 1, explanation: 'Uncontrolled modifications can invalidate certification and protection. The discrepancy must be documented and reviewed under formal management of change.', relatedLessonId: 'installation-fundamentals' },
  ] },
  { id: 'inspection-lifecycle', title: 'Inspection and lifecycle decisions', level: 'Advanced', description: 'Practise findings, records, repair boundaries, and return-to-service decisions.', lessonIds: ['ex008-inspection', 'maintenance-repair-overhaul', 'documentation-and-records'], questions: [
    { id: 'q-lifecycle-1', prompt: 'Under IEC 60079-17, what elements are necessary for an Ex inspection finding to be technically defensible and actionable', options: ['A generalized note stating that the overall equipment condition appears satisfactory', 'An unannotated photograph filed without equipment tag numbers or location details', 'Clear asset identification, location, specific observation referenced to standards, assigned priority, and designated action owner', 'An informal verbal notification given to operating personnel during shift change'], correctAnswer: 2, explanation: 'An effective inspection finding links traceable asset identification with precise physical observations, standard non-conformity references, and responsible ownership.', relatedLessonId: 'ex008-inspection' },
    { id: 'q-lifecycle-2', prompt: 'Motor SN-998 is returned from overhaul. The repair report is missing the stator rewinding dimensional data. What must occur before it is returned to service?', options: ['Immediate energization if the motor operates normally under no-load testing', 'Assumption that certified protection integrity is preserved if original bolts are fitted', 'Discarding the repair paperwork to avoid conflicting historical maintenance records', 'Maintaining the motor in a safe isolated state until the missing rewinding data is verified by a competent repair facility under IEC 60079-19'], correctAnswer: 3, explanation: 'IEC 60079-19 governs repair and overhaul. If critical repair data (like rewinding dimensions) is missing, the equipment must not be returned to hazardous service until verified.', relatedLessonId: 'maintenance-repair-overhaul' },
  ] },
  { id: 'competence-boundaries', title: 'Competence and scheme boundaries', level: 'Advanced', description: 'Reinforce CoPC, RTP, ExCB, escalation, and responsibility boundaries.', lessonIds: ['copc-rtp-excb', 'competence-and-responsibilities'], questions: [

    { id: 'q-competence-2', prompt: 'During inspection of Junction Box JB-500, the certification label is missing the ambient temperature range, and the manual is unavailable on site. What is the defensible response?', options: ['Proceed with sign-off based on assumptions from an adjacent junction box of similar appearance', 'Record the missing ambient temperature data, maintain safe control, and escalate to the engineering authority or manufacturer for formal verification', 'Select the standard -20°C to +40°C range to avoid maintenance delays and sign off the inspection', 'Assume default Zone 2 conformity and record the ambient temperature as standard without checking further'], correctAnswer: 1, explanation: 'Incomplete certification evidence is an uncontrolled risk. The gap must be recorded and formally resolved by contacting the manufacturer or site engineering authority before acceptance.', relatedLessonId: 'competence-and-responsibilities' },
  ] },
  { id: 'integrated-review', title: 'Integrated Ex decision review', level: 'Advanced', description: 'Bring area, equipment, installation, inspection, maintenance, and competence together.', lessonIds: ['integrated-ex-workshop'], questions: [
    { id: 'q-integrated-1', prompt: 'An area classification drawing specifies Zone 1, Group IIB, T3. An installed motor is marked Ex ec IIA T4 Gc. What non-conformities exist?', options: ['None, because T4 (135°C) is better than T3 (200°C) and Ex ec is a recognized protection concept', 'The gas group (IIA installed vs IIB required) and the Equipment Protection Level (Gc installed vs Gb required for Zone 1) are non-compliant', 'Only the Equipment Protection Level (Gc installed vs Gb required) is non-compliant', 'Only the gas group (IIA installed vs IIB required) is non-compliant, as Gc is acceptable in Zone 1'], correctAnswer: 1, explanation: 'The installation fails on both Gas Group (IIA cannot be used where IIB is required) and EPL (Gc is only permitted in Zone 2, not Zone 1). The favorable T4 rating does not override these fundamental mismatches.', relatedLessonId: 'integrated-ex-workshop' },
  ] },
]

const phase6Quizzes: Quiz[] = [
  { id: 'ex007-installation-practice', title: 'EX007 installation practice', level: 'Intermediate', description: 'Apply evidence-led installation checks for entries, bonding, segregation, and protection.', lessonIds: ['ex007-installation-practice', 'installation-fundamentals', 'glands-and-cable-entries'], questions: [
    phase6Question('q-ex007-01', "During the initial installation verification of an Ex eb increased safety terminal box under IEC 60079-14, which documents must be cross-referenced against the physical field installation", ["The manufacturer's standard commercial catalogue cut-sheet and the mechanical piping isometric drawing", "The hazardous area classification drawing, equipment certificate schedule, manufacturer instructions, and cable/earthing design schedule", "The general plant architectural elevation drawing and the civil foundation handover certificate", "The control system functional design specification and software logic flowchart"], 1, "the verification dossier must contain the area classification documentation, equipment certificates and schedules, manufacturer installation instructions, and design schedules detailing cable and earthing parameters to confirm field compliance before energization.", 'ex007-installation-practice'),
    phase6Question('q-ex007-02', 'Why are unused enclosure openings significant', ['Openings compromise enclosure ingress protection, flameproof containment, or increased safety boundaries unless fitted with certified stopping plugs', 'Openings provide necessary internal natural ventilation for Ex d flameproof enclosures', 'Openings indicate that the internal wiring is intrinsically safe and self-limiting', 'Openings are purely cosmetic considerations that do not influence explosion safety'], 0, 'An unused opening compromises ingress protection, flameproof containment, or increased safety boundaries.', 'ex007-installation-practice'),
    phase6Question('q-ex007-03', "An installer needs to fit an M20 certified Ex d cable gland into an Ex d junction box that has M25 threaded entry holes. Under IEC 60079-14, which method is technically compliant", ["Wrap the M20 gland threads in lead foil or excess PTFE tape until it achieves a tight mechanical fit in the M25 hole", "Install a certified Ex d thread adaptor (M25 male to M20 female) with matching thread pitch and certified IP washer", "Install two generic non-certified threaded brass reducers in series to step down the entry thread size", "Machine the M25 entry hole on site using a hand tap to create an oversized non-standard thread form"], 1, "thread adaptors must be certified Ex components matching the enclosure protection concept and thread form. Using PTFE tape to bridge thread size differences or cascading multiple adaptors is strictly prohibited.", 'ex007-installation-practice'),
    phase6Question('q-ex007-04', 'Which observation is most useful in a finding', ['Motor control station enclosure reported as appearing generally worn and weathered', 'Field electrical box requires inspection follow-up before next operational shutdown', 'Asset JB-14, east entry: sealing ring visibly split and outer sheath retracted 15 mm, exposing unarmoured cores', 'Terminal assembly examined visually and presumed operational under current load'], 2, 'Asset identity, precise entry location, and observable physical condition make an inspection finding actionable.', 'ex007-installation-practice', 'finding'),
    phase6Question('q-ex007-05', 'What does bonding evidence help demonstrate', ['That the equipment was manufactured within the preceding calendar year', 'That the enclosure has achieved an ingress protection rating of IP68', 'That the hazardous area has been officially derated to a non-hazardous classification', 'That equipotential bonding and earth continuity comply with design specifications to prevent dangerous potential differences'], 3, 'Bonding is an installation control that must be verified against design specifications to prevent dangerous potential differences.', 'ex007-installation-practice'),
    phase6Question('q-ex007-06', 'Should an inspector fit an unverified substitute plug to close a finding', ['No; stopping plugs must be certified Ex components matching the enclosure thread form, material, and protection concept', 'Yes, provided the plug threads engage hand-tight into the enclosure wall', 'Yes, if an uncertified industrial plug is coated with commercial thread-locking sealant', 'Yes, provided the installation is located in Zone 2 where explosive atmospheres are rare'], 0, 'Stopping plugs must be certified Ex components matching thread form, material, and protection concept.', 'glands-and-cable-entries'),
    phase6Question('q-ex007-07', 'What can a changed cable route affect', ['Only the cosmetic labeling tags applied at terminal junction boxes', 'Circuit segregation, mechanical and thermal protection, and hazardous area zone boundary crossings', 'Nothing, provided the conductor loop resistance remains within instrument limits', 'Only the ambient temperature rating printed on the primary distribution board'], 1, 'Routing can affect circuit segregation, mechanical protection, and documented design assumptions under IEC 60079-14.', 'ex007-installation-practice'),
    phase6Question('q-ex007-10', "An inspector arrives at a pump skid with an inspection ticket for motor P-101B (duty/standby service). The field motor at that physical location is tagged P-101A. What is the required technical action under IEC 60079-17", ["Perform the inspection and sign off P-101B, assuming identical mechanical and electrical duty", "Deface tag P-101A with a hand punch and re-tag it as P-101B to match the work order", "Hold the inspection, record the tag discrepancy, verify the plant P&ID/equipment register, and ensure both assets are correctly identified before completing records", "Complete the inspection as P-101B but note in the free-text comments that the motor may be P-101A"], 2, "equipment register traceability is safety-critical. Inspecting an asset with a mismatched tag invalidates historical records, risks missing unverified equipment, and corrupts maintenance dossier integrity. The conflict must be resolved with controlled engineering data.", 'ex007-installation-practice', 'finding'),
  ] },
  { id: 'ex-d-decisions', title: 'Ex d decisions', level: 'Intermediate', description: 'Practise flameproof enclosure observations and repair boundaries.', lessonIds: ['ex-d-flameproof', 'ex-d-ex-e'], questions: [
    phase6Question('q-exd-01', 'What is central to an Ex d enclosure', ['Maintaining a continuous internal overpressure using protective inert gas purging', 'Withstanding an internal explosion and cooling escaping hot gases across flamepaths to prevent external ignition', 'Restricting circuit electrical energy below the minimum ignition energy of the surrounding gas', 'Employing high-integrity double insulation and ensuring no moving mechanical parts are enclosed'], 1, 'The enclosure and its flamepaths are designed to contain an internal explosion and cool escaping combustion gases.', 'ex-d-flameproof'),
    phase6Question('q-exd-02', 'Why can incorrect fasteners matter', ['They alter the external IP rating without affecting explosion containment', 'Non-certified standard bolts always provide superior tensile strength in high-temperature zones', 'Incorrect property class or length can shear under explosion overpressure or distort flamepath gap dimensions', 'Fastener specifications are commercial purchasing preferences with no safety significance'], 2, 'Fastener specification, yield strength, and correct thread engagement are safety-critical to maintain flamepath integrity under explosion pressure.', 'ex-d-flameproof'),
    phase6Question('q-exd-03', 'What should be done with a visibly scored flamepath', ['Dress and file the joint surface on site until the gouge is visually smooth', 'Apply a heavy bead of RTV silicone sealant across the flange before bolting closed', 'Over-torque the cover fixing bolts to compress the joint across the damaged area', 'Measure the defect depth, record the condition, and submit for competent assessment against manufacturer tolerances and IEC 60079-19'], 3, 'A damaged flamepath requires controlled measurement and competent assessment against manufacturer tolerances and IEC 60079-19.', 'ex-d-flameproof', 'finding'),
    phase6Question('q-exd-04', 'Does a closed cover prove an Ex d condition is acceptable', ['No; flamepath gap width, surface condition, internal components, bolt torque, and certified entries must also be verified', 'Yes, a visually closed cover guarantees flameproof containment regardless of joint gap dimensions', 'Only when the equipment is installed in an outdoor sheltered Zone 2 environment', 'Only if the enclosure casting wall thickness exceeds 10 mm'], 0, 'Visual cover closure alone is not proof of protection integrity; flamepath gap, bolts, and entries must be verified.', 'ex-d-flameproof'),
    phase6Question('q-exd-05', 'Which of the following constitutes an unapproved alteration to an Ex d flameproof enclosure?', ['Replacing an internal terminal block using the exact manufacturer part number specified in the certificate schedule', 'Drilling a new M20 cable entry using standard workshop tools to accommodate an additional sensor', 'Replacing a damaged cover gasket with a new one of identical material specification supplied by the original manufacturer', 'Installing a plug-in relay specifically listed as an approved accessory in the manufacturer equipment instructions'], 1, 'Drilling new entries or machining an Ex d enclosure alters the flameproof integrity and invalidates certification unless explicitly permitted by the certificate and performed strictly to manufacturer instructions.', 'ex-d-flameproof', 'knowledge'),
    phase6Question('q-exd-06', 'What should an inspector avoid doing to a flamepath', ['Measuring flamepath gap clearances with calibrated feeler gauges', 'Verifying the property class marked on the enclosure cover bolts', 'Unauthorised filing, grinding, painting, or applying gasket material to machined joint surfaces', 'Applying a thin film of approved non-setting, non-metallic anti-corrosion grease'], 2, 'Machining, grinding, filing, painting, or applying non-specified sealants to a flamepath is strictly prohibited during inspection.', 'ex-d-flameproof'),
    phase6Question('q-exd-07', 'Why record the extent of corrosion', ['It establishes that the enclosure has achieved complete galvanic isolation', 'It proves that environmental moisture cannot penetrate into terminal connections', 'It eliminates the need for future periodic visual inspections under IEC 60079-17', 'It enables competent evaluation of wall thickness loss, joint pitting depth, and fastener degradation against allowable limits'], 3, 'Corrosion extent and pitting location provide essential data for competent evaluation against permissible overhaul limits.', 'ex-d-flameproof', 'finding'),
    phase6Question('q-exd-08', 'Which is an appropriate first action for a damaged enclosure', ['Ensure the circuit is safely isolated or controlled, document the damage, and raise a formal non-conformity report', 'Force the deformed cover closed using an oversized lever or impact tool', 'Substitute unverified bolts from general warehouse stock to draw the flange together', 'De-register the equipment asset tag so the defect does not appear on inspection audits'], 0, 'Immediate isolation and formal documentation must precede any approved repair decision.', 'ex-d-flameproof'),
    phase6Question('q-exd-09', 'An Ex db motor certificate guarantees the internal explosion containment of the motor itself. Which of the following installation aspects does the equipment certificate NOT automatically guarantee?', ['That the motor enclosure can withstand the reference pressure of an internal gas explosion', 'That the installed cable gland, obstacle clearance from the flange, and external earthing continuity comply with IEC 60079-14', 'That the maximum surface temperature will not exceed the marked temperature class during normal operation', 'That the flamepath gap dimensions comply with the manufacturing standard IEC 60079-1'], 1, 'An Ex db equipment certificate covers the manufactured equipment. Field installation aspects like specific cable gland selection, obstacle clearance from flanged joints, and earthing must be verified separately under IEC 60079-14.', 'ex-d-flameproof', 'knowledge'),
    phase6Question('q-exd-10', 'What should a repair route include', ['A new field rating plate stamped on site without documented repair measurements', 'Informal welding of casting cracks followed by cosmetic grinding and repainting', 'Compliance with IEC 60079-19, verified manufacturer repair limits, competent certified personnel, and traceable overhaul records', 'An oral assurance from the contractor that the motor was tested off-site'], 2, 'Repairs must adhere to IEC 60079-19 using approved methods, competent personnel, and traceable return-to-service records.', 'ex-d-flameproof'),
  ] },
  { id: 'ex-e-decisions', title: 'Ex e decisions', level: 'Intermediate', description: 'Review increased-safety termination, clearance, and thermal observations.', lessonIds: ['ex-e-increased-safety', 'ex-d-ex-e'], questions: [
    phase6Question('q-exe-01', 'What is the broad intent of Ex e', ['To provide an explosion-containment boundary capable of withstanding internal deflagrations', 'To limit electrical energy to levels incapable of igniting flammable gas under fault conditions', 'To purge the enclosure continuously with protective gas to maintain positive pressure', 'To apply increased constructional measures preventing arcs, sparks, and excessive surface temperatures in normal operation and specified abnormal conditions'], 3, 'Ex e applies constructional and thermal measures to prevent arcs, sparks, and excessive temperatures.', 'ex-e-increased-safety'),
    phase6Question('q-exe-02', 'Which field evidence is relevant at a termination', ['Conductor strand consolidation, specified torque, evidence of overheating, and creepage and clearance distances', 'External paint coating thickness and RAL colour matching on the outer enclosure', 'The calendar year of manufacture stamped on adjacent non-electrical brackets', 'The occupational trade classification of the commissioning technician'], 0, 'Termination workmanship, strand consolidation, torque, and thermal evidence directly affect Ex e protection integrity.', 'ex-e-increased-safety'),
    phase6Question('q-exe-03', 'What can heat discolouration indicate', ['Normal operating conditions that verify self-cleaning terminal contact performance', 'Loose connections, overcurrent, or high contact resistance that may exceed temperature class limits or degrade insulation', 'Proof that the enclosure internal heating conforms to the certified limiting temperature', 'A positive indication that conductor termination torque was correctly applied'], 1, 'Heat discolouration points to excessive local temperature, loose connections, or contact degradation requiring investigation.', 'ex-e-increased-safety', 'finding'),
    phase6Question('q-exe-04', 'Why check accessories against documentation', ['Because accessories eliminate the requirement for periodic inspection under IEC 60079-17', 'Because uncertified components can be freely substituted if their physical thread matches', 'Because uncertified or incompatible breathers, drains, and stopping plugs can compromise IP rating and creepage distances', 'Because manufacturer drawings automatically expire once an accessory is fitted in the field'], 2, 'Unverified accessories can degrade ingress protection, reduce clearance distances, or invalidate certification.', 'ex-e-increased-safety'),
    phase6Question('q-exe-05', 'What is a weak inspection statement', ['Asset JB-04, terminal 3: localized thermal discolouration observed on insulation collar; torque verified at 1.2 Nm against 2.0 Nm specification', 'Enclosure cover seal intact, gasket seated continuously, and ingress protection verified as IP66', 'Cable entry 2 fitted with certified Ex eb stopping plug with intact elastomeric sealing washer', 'Enclosure looks fine from floor level without ladder access or verifying internal terminal condition'], 3, 'A vague conclusion from distant visual viewing does not establish internal terminal condition, torque, or clearance integrity.', 'ex-e-increased-safety', 'finding'),
    phase6Question('q-exe-06', 'What should happen when clearance acceptability is unknown', ['Verify the required creepage and clearance distances against IEC 60079-7 rated voltage tables and manufacturer documentation', 'Assume clearances are acceptable if conductors do not touch when bent by hand', 'Trim internal insulating terminal partitions with side cutters to fit oversized lugs', 'Energize the circuit and check if an earth leakage fault is detected by the protection relay'], 0, 'Unknown clearances require measurement and verification against IEC 60079-7 tables and manufacturer documentation.', 'ex-e-increased-safety'),
    phase6Question('q-exe-07', 'Does a tidy enclosure prove Ex e suitability', ['Yes, clean internal appearance guarantees that temperature ratings and creepage limits are satisfied', 'No; terminal torque, conductor sizing, temperature class limits, and certified entry compatibility must still be verified', 'Only when installed in a dedicated indoor plant room with climate control', 'Only if the enclosure carries a manufacturer nameplate dated within the last two years'], 1, 'Internal cleanliness is only one factor; verified conductor sizing, torque, terminal approvals, and thermal limits are required.', 'ex-e-increased-safety'),
    phase6Question('q-exe-08', 'Why can conductor preparation matter', ['It automatically elevates equipment from EPL Gc to EPL Gb', 'It changes the flammable gas group from Group IIA to Group IIC', 'Proper ferrule crimping and strand consolidation prevent stray wires, high resistance hotspots, and insulation damage', 'It eliminates the need for an external equipotential bonding conductor'], 2, 'Conductor preparation prevents loose strands, reduces contact resistance hotspots, and protects insulation integrity.', 'ex-e-increased-safety'),
    phase6Question('q-exe-09', 'What is a safe response to an unexplained hot spot', ['Apply thermal insulation wrap around the enclosure to hide the hot spot from infrared cameras', 'Increase motor load to test whether the thermal trip trips within certified limits', 'Conclude that the condition is acceptable because Ex eb enclosures are designed to run hot', 'Control the condition, record thermal measurements, and investigate root cause before returning to service'], 3, 'Unexplained thermal hotspots must be isolated, recorded, and investigated before equipment is accepted for service.', 'ex-e-increased-safety', 'finding'),
    phase6Question('q-exe-10', 'What is the significance of the tE time marked on an Ex eb motor?', ['It defines the periodic inspection interval in months', 'It represents the time taken for the motor to reach its maximum surface temperature during normal operation', 'It is the time within which the motor protection device must trip if the rotor locks (stalls), preventing the limiting temperature from being exceeded', 'It indicates the time required for internal hot components to cool to ambient temperature after isolation'], 2, 'The tE time is a critical Ex eb parameter; it defines the maximum time the motor can withstand a locked rotor condition before exceeding its certified limiting temperature. The protection relay must trip within this time.', 'ex-e-increased-safety', 'knowledge'),
  ] },
  { id: 'ex-i-calculations', title: 'Ex i and IS calculations', level: 'Advanced', description: 'Practise complete-loop thinking and transparent arithmetic.', lessonIds: ['ex-i-intrinsic-safety', 'ex-i-ex-t-ex-p'], questions: [
    phase6Question('q-exi-01', 'What does intrinsic-safety review cover', ['Only the nameplate certification code of the field instrument located in the hazardous area', 'The complete loop comprising barrier/isolator, interconnecting cable parameters, and field device entity parameters', 'Only verifying that the interconnecting cable has a light blue outer sheath', 'Only confirming that the control room marshalling cabinet is fitted with an exhaust fan'], 1, 'Intrinsic safety is a system concept requiring analysis of the barrier, cable, and field device as an integrated loop.', 'ex-i-intrinsic-safety'),
    phase6Question('q-exi-02', 'In an Ex i loop evaluation, a barrier provides Uo = 28 V, Io = 93 mA, Po = 0.65 W, Co = 83 nF. The transmitter has Ui = 30 V, Ii = 100 mA, Pi = 0.75 W, Ci = 12 nF (with negligible internal inductance Li), with 200 m of cable (Cc = 200 pF/m = 40 nF). What is the compliance status of the circuit', ['The loop is non-compliant because Ui (30 V) is greater than Uo (28 V)', 'The loop is non-compliant because the total inductance (0.6 mH) exceeds Lo (4.2 mH)', 'The stated parameters are compliant: Ui >= Uo, Ii >= Io, Pi >= Po, and total capacitance (52 nF) is <= Co (83 nF)', 'The loop is non-compliant because total capacitance (52 nF) must be zero in an intrinsically safe circuit'], 2, 'For the evaluated parameters, field apparatus ratings withstand barrier output (Ui >= Uo, Ii >= Io, Pi >= Po) and total capacitance Ci + Cc = 12 nF + 40 nF = 52 nF <= Co (83 nF). Because internal inductance Li is negligible, the 50% mixed lumped parameter derating rule.2 does not apply.', 'ex-i-intrinsic-safety', 'calculation'),
    phase6Question('q-exi-03', 'An intrinsically safe sensor dissipates 0.36 W (24 V * 15 mA) in a 40°C ambient with an internal thermal resistance Rth of 100 K/W. What is the calculated surface temperature and T-class compliance', ['3.6°C rise above ambient temperature', '100°C rise above ambient temperature', '24°C rise above ambient temperature', '36°C rise, resulting in a maximum surface temperature of 76°C (compliant with T6)'], 3, 'Temperature rise equals power multiplied by thermal resistance: 0.36 W * 100 K/W = 36 K. In a 40°C ambient, max surface temperature is 76°C, which complies with T6.', 'ex-i-intrinsic-safety', 'calculation'),
    phase6Question('q-exi-04', 'Why show units in an IS practice calculation', ['Unit conversion errors between microfarads, nanofarads, and picofarads can cause severe miscalculation of permitted cable capacitance and spark ignition thresholds', 'Converting units automatically certifies an intrinsically safe loop under IECEx 05', 'Correct unit notation eliminates the need to verify field device Ui and Ii entity parameters', 'Unit labels determine whether an associated apparatus is classified as Ex ia or Ex ib'], 0, 'Units expose unit-conversion errors between microfarads, nanofarads, and millihenries that can compromise spark ignition assessments.', 'ex-i-intrinsic-safety', 'calculation'),
    phase6Question('q-exi-05', 'Which item is part of a loop review', ['Only the enclosure IP rating and motor starter trip characteristics in the safe area', 'Associated apparatus output parameters, interconnecting cable L/R ratio and length, field device entity parameters, and earthing topology', 'Only the RAL colour code of the light blue terminal insulation collars', 'Only confirming that the field transmitter is mounted at least 2 metres above finished floor level'], 1, 'A complete loop review covers barrier parameters, cable capacitance and inductance, field device ratings, and earthing topology.', 'ex-i-intrinsic-safety'),
    phase6Question('q-exi-06', 'A 4-pair instrument cable has an inductance of 650 μH/km and resistance of 25 Ω/km. If the barrier permits an Lo/Ro ratio of 40 μH/Ω, what is the cable L/R ratio and is it compliant', ['65 μH/Ω, which exceeds the barrier limit and is non-compliant', '16.25 μH/Ω, which is non-compliant because it must equal exactly 40 μH/Ω', '26 μH/Ω (650 / 25), which is less than 40 μH/Ω and therefore compliant', '260 μH/Ω, which requires an additional series resistor in the hazardous area'], 2, 'The cable L/R ratio is 650 μH/km divided by 25 Ω/km = 26 μH/Ω. Since 26 μH/Ω is less than Lo/Ro (40 μH/Ω), the cable satisfies the permitted ratio.', 'ex-i-intrinsic-safety', 'calculation'),
    phase6Question('q-exi-07', 'An IS barrier output is Uo=24V, Io=100mA, Po=0.6W, Co=120nF. The field device is Ui=30V, Ii=120mA, Pi=0.8W, Ci=20nF. The cable has Cc=150nF. Why is this loop non-compliant?', ['Because the power output Po (0.6W) exceeds the field device Pi (0.8W)', 'Because the total capacitance (Ci + Cc = 170nF) exceeds the barrier permitted maximum Co (120nF), risking a spark ignition', 'Because the voltage Ui (30V) is greater than Uo (24V)', 'Because the current Ii (120mA) is greater than Io (100mA)'], 1, 'While voltage, current, and power parameters are acceptable (Ui>=Uo, Ii>=Io, Pi>=Po), the total loop capacitance (20nF + 150nF = 170nF) exceeds the barrier limit (120nF), compromising the energy limitation of the circuit.', 'ex-i-intrinsic-safety', 'calculation'),
    phase6Question('q-exi-08', 'Why does segregation matter in IS installation', ['To prevent dangerous electrostatic or electromagnetic cross-coupling and fault voltages from invading the energy-limited IS circuit', 'To lower the auto-ignition temperature of flammable gases surrounding the cable tray', 'To replace the requirement for barrier grounding in galvanic isolator installations', 'To prove that the external cable armor satisfies Ex d flameproof mechanical requirements'], 0, 'Segregation prevents non-IS power circuits from inducing dangerous fault voltages or spark energy into the energy-limited IS wiring.', 'ex-i-intrinsic-safety'),
    phase6Question('q-exi-09', 'What should be done with missing entity data', ['Assume standard default generic values based on typical 4-20 mA instrumentation', 'Do not approve the loop; hold commissioning until certified manufacturer certificates and entity data are verified', 'Increase barrier supply voltage to compensate for unknown internal circuit impedance', 'Remove the safety barrier and connect the field instrument directly to standard DCS I/O cards'], 1, 'Missing entity data prevents safe assessment; commissioning must be held until verified parameters are obtained.', 'ex-i-intrinsic-safety', 'finding'),

  ] },
  { id: 'ex-t-dust-decisions', title: 'Ex t dust decisions', level: 'Intermediate', description: 'Connect dust ingress, deposits, temperature, and housekeeping controls.', lessonIds: ['ex-t-dust-protection', 'gas-vapour-mist-dust'], questions: [
    phase6Question('q-ext-01', 'What does Ex t depend on', ['Continuous extraction fans venting explosive dust clouds directly to atmosphere', 'Measuring ambient relative humidity to ensure dust particles remain moist', 'Installing flamepath flanges with narrow gaps matched to maximum experimental safe gap', 'Enclosure dust exclusion (IP5X or IP6X) and limiting maximum external surface temperature below dust ignition temperatures'], 3, 'Dust ignition protection Ex t relies on enclosure dust exclusion (IP rating) and limiting surface temperatures below ignition thresholds.', 'ex-t-dust-protection'),
    phase6Question('q-ext-02', 'Why can a dust layer be significant', ['It thermally insulates equipment causing surface temperature runaway and can be disturbed into an explosive dust cloud', 'It lowers the operating temperature of enclosed electrical apparatus through conduction', 'It provides proof that local ventilation has eliminated all dust cloud hazards', 'It creates a protective oxygen-depleted barrier that prevents spontaneous combustion'], 0, 'Dust layers insulate equipment surfaces leading to thermal runaway, and can be disturbed into combustible airborne dust clouds.', 'ex-t-dust-protection'),
    phase6Question('q-ext-03', 'What should a missing gasket trigger', ['Immediate energization provided the enclosure lid bolts are torqued down firmly', 'A documented non-conformity finding and replacement with an approved manufacturer gasket to restore certified IP rating', 'Using compressed air to blow accumulated dust through the open enclosure seams', 'Applying household silicone caulk along the external seam without recording the change'], 1, 'A missing gasket compromises the dust-tight enclosure boundary and IP rating, requiring documented replacement with approved parts.', 'ex-t-dust-protection', 'finding'),
    phase6Question('q-ext-04', 'What is unsafe housekeeping practice', ['Recording dust layer thickness and reporting abnormal process accumulation to operations', 'Using an approved hazardous-location rated vacuum cleaner complying with IEC 60079-31', 'Using compressed air lances to blow settled dust off overhead cable trays and enclosures, creating airborne clouds', 'Gentle wet cleaning following approved site procedures while equipment is de-energized'], 2, 'Blowing settled dust with compressed air creates airborne dust clouds that can be ignited by electrical or hot surfaces.', 'ex-t-dust-protection'),
    phase6Question('q-ext-05', 'Which enclosure feature should be observed', ['Only the ambient light level from adjacent high-bay floodlights', 'Only the serial number format stamped on the internal DIN rail', 'Only the RAL paint code of the external structural support steelwork', 'Gasket resilience, joint cleanliness, cable gland sealing, cover flatness, and bolt torque integrity'], 3, 'Gasket condition, joint surfaces, certified cable entries, cover alignment, and fasteners collectively maintain the dust-tight barrier.', 'ex-t-dust-protection'),
    phase6Question('q-ext-06', 'What should happen if the temperature limit source is missing', ['Do not energize; verify equipment marked surface temperature T against dust cloud (Tcloud) and layer (T5mm) ignition temperatures', 'Estimate the maximum surface temperature based on average seasonal outdoor temperatures', 'Remove the nameplate and re-classify the equipment as general-purpose industrial equipment', 'Assume the apparatus conforms to T6 (85°C) if the housing feels warm but not hot to touch'], 0, 'Surface temperature limits must be formally verified against dust cloud and layer ignition temperatures before energizing.', 'ex-t-dust-protection', 'finding'),
    phase6Question('q-ext-07', 'Does Ex t make housekeeping irrelevant', ['Yes, Ex t enclosures are completely immune to thermal degradation from any dust depth', 'No; excessive dust layers exceed certified 5 mm test depth, cause heat buildup, and demand controlled housekeeping', 'Only in Zone 20 areas where continuous dust clouds prevent layer accumulation', 'Only after an initial detailed inspection has been signed off by the site engineer'], 1, 'Housekeeping remains vital because excessive dust layers insulate the enclosure, increase surface temperatures, and can exceed standard 5 mm testing limits.', 'ex-t-dust-protection'),
    phase6Question('q-ext-08', 'Why record where dust is deposited', ['Because recording location automatically reduces the hazardous zone classification from Zone 21 to Zone 22', 'Because marking the location issues an operational waiver under international standards', 'Because deposit location correlates dust accumulation with equipment thermal dissipation and process release sources', 'Because logging the deposit coordinates eliminates the need for physical cleaning'], 2, 'Recording exact deposit locations correlates dust buildup with equipment heat sources and identifies unmanaged release points.', 'ex-t-dust-protection', 'finding'),
    phase6Question('q-ext-09', 'What is a cautious response to a compromised dust enclosure', ['Assume the accumulated dust is non-combustible without laboratory test verification', 'Wrap masking tape around the compromised joint and maintain full electrical load', 'Increase process throughput to blow away dust deposits with natural building drafts', 'Isolate electrical supply if safety-critical, control the condition, and initiate formal defect rectification'], 3, 'A compromised dust enclosure presents immediate ignition risk; isolate if safety-critical and initiate formal rectification.', 'ex-t-dust-protection'),

  ] },
  { id: 'ex-p-operational-controls', title: 'Ex p operational controls', level: 'Advanced', description: 'Review purge, pressure, alarms, and response to protective-condition loss.', lessonIds: ['ex-p-pressurization', 'ex-i-ex-t-ex-p'], questions: [
    phase6Question('q-exp-01', 'What maintains Ex p protection', ['A certified rating label regardless of whether protective gas supply is connected', 'Maintaining a continuous flow or positive overpressure of protective gas (air or inert) with monitored safety interlocks', 'Keeping the surrounding substation floor clean and free of combustible debris', 'Fitting an external flame arrestor over the enclosure exhaust ventilation port'], 1, 'Ex p protection depends on continuous positive overpressure or purge flow of protective gas with monitored interlocks.', 'ex-p-pressurization'),
    phase6Question('q-exp-02', 'Why are alarms part of Ex p', ['They provide proof that the operator possesses valid competence credentials', 'They eliminate the requirement for mechanical enclosure strength and seals', 'They provide immediate audible/visual warning upon loss of minimum overpressure, triggering controlled response or trip', 'They reclassify the surrounding area to a lower hazard zone while active'], 2, 'Alarms signal loss or drop of protective overpressure, initiating immediate operator intervention or automated disconnection.', 'ex-p-pressurization'),
    phase6Question('q-exp-03', 'What should happen after repeated low-pressure alarms', ['Assume the pressure differential transmitter has failed and silence the audible beacon', 'Lower the minimum pressure threshold setting in the controller to prevent nuisance alarms', 'Install an electrical jumper across the pressure switch contacts to bypass the trip circuit', 'Investigate enclosure door seals, cable gland leakage, and supply flow, executing the approved safety response'], 3, 'Repeated low-pressure alarms indicate active leakage or pressure loss that must be investigated and resolved under approved procedures.', 'ex-p-pressurization', 'finding'),
    phase6Question('q-exp-04', 'What can an open door affect', ['It breaches the protective boundary, collapses overpressure, and risks immediate ingress of flammable gas into energized apparatus', 'It only damages the external surface paint finish on the enclosure door hinges', 'It increases the maximum surface temperature rating of internal busbars', 'It has no safety impact if the enclosure exhaust duct is fitted with an outlet damper'], 0, 'Opening an enclosure door collapses protective overpressure and can allow surrounding explosive atmospheres to reach internal non-Ex components.', 'ex-p-pressurization'),
    phase6Question('q-exp-05', 'Why check procedure revision', ['To confirm that the equipment was commissioned during the current financial year', 'Because purge durations, minimum flow rates, and safety interlock trip sequences may have been updated in controlled engineering revisions', 'Because an updated operating manual replaces physical calibration of pressure sensors', 'Because operating procedures grant statutory equipment certification under ATEX directive 2014/34/EU'], 1, 'Operating sequence, purge volume times, and protective interlock actions must align with the current controlled engineering documentation.', 'ex-p-pressurization'),
    phase6Question('q-exp-06', 'During planned maintenance, an Ex p pressure trip is bypassed under a formal Management of Change (MOC) to allow troubleshooting. Which additional controls are typically required?', ['Continuous atmospheric gas monitoring and a documented permit-to-work specifying immediate isolation if gas is detected', 'None, because the MOC paperwork automatically ensures the area is free of explosive gas', 'A secondary mechanical lock on the enclosure door to prevent unauthorized entry', 'Reducing the internal pressure setpoint to zero so that the purge fan can be turned off completely'], 0, 'Bypassing safety-critical Ex p interlocks removes automatic explosion protection. This requires robust compensatory measures such as continuous gas monitoring and strict permit controls to ensure the area remains non-hazardous.', 'ex-p-pressurization', 'knowledge'),
    phase6Question('q-exp-07', 'What should an operator preserve after a trip', ['A newly fabricated equipment label attached over the old serial plate', 'An informal verbal description provided to maintenance contractors at shift end', 'A cleared alarm history log to reset the annunciator panel before investigation', 'Timestamped purge status, pressure trend logs, alarm sequence data, and physical plant conditions'], 3, 'Preserving timestamped pressure logs, alarm sequences, and field evidence enables competent root-cause diagnosis.', 'ex-p-pressurization', 'finding'),
    phase6Question('q-exp-08', 'Which check relates directly to pressure retention', ['Gasket resilience, door latch compression, cable entry seals, and air supply regulator pressure', 'External enclosure RAL paint colour matching plant design specifications', 'The badge accreditation number of the instrumentation calibration vendor', 'The layout and distance of control room furniture from the marshalling rack'], 0, 'Door gaskets, latch compression, and cable gland sealing directly determine enclosure pressure retention and leakage rates.', 'ex-p-pressurization'),
    phase6Question('q-exp-09', 'What is the right response to unknown purge timing', ['Estimate a purge duration of 60 seconds based on standard industrial fan timers', 'Verify certified minimum volume changes and purge time from manufacturer documentation before energizing', 'Bypass the purge cycle and energize directly if no gas odor is detected near the cabinet', 'Disable the pre-purge timer interlock in the PLC to avoid startup delays'], 1, 'Purge duration depends on enclosure volume and minimum volume changes; it must be verified from certified documentation.', 'ex-p-pressurization'),
    phase6Question('q-exp-10', 'What is the fundamental purpose of the pre-purge sequence in an Ex p pressurized enclosure system?', ['To cool the internal electronic components before they are subjected to full electrical load', 'To flush out any flammable gas that may have entered the enclosure before electrical power is applied to non-Ex internal equipment', 'To pressurize the enclosure to 500 millibars so that it can withstand physical impacts', 'To calibrate the differential pressure sensors by taking them to their maximum full-scale reading'], 1, 'The pre-purge sequence guarantees that a minimum number of enclosure volumes of protective gas flow through the housing to sweep away any accumulated explosive mixtures before ignition sources are energized.', 'ex-p-pressurization', 'knowledge'),
  ] },
  { id: 'glands-and-marking', title: 'Glands and marking', level: 'Intermediate', description: 'Practise entry compatibility and complete marking review.', lessonIds: ['glands-and-cable-entries', 'equipment-selection-marking'], questions: [
    phase6Question('q-gland-01', 'Why is a gland more than a hole filler', ['It serves as an independent electrical isolation switch for field circuits', 'It changes the explosive gas group from Group IIC down to Group IIA', 'It eliminates the requirement for equipotential bonding of cable armor', 'It maintains enclosure ingress protection, flameproof containment, cable retention, and earth continuity'], 3, 'A certified cable gland provides cable retention, environmental sealing, earth continuity, and preserves enclosure protection.', 'glands-and-cable-entries'),
    phase6Question('q-gland-02', 'What does physical fit prove', ['Physical thread engagement alone does not establish compatibility with cable type, protection concept, or certified schedule', 'Thread fit provides conclusive proof that the cable gland matches the enclosure certification', 'If a gland screws in, it automatically satisfies all IEC 60079-14 installation rules', 'Physical fit certifies that the internal elastomeric seal matches the cable diameter'], 0, 'Physical thread fit alone does not confirm that the gland is compatible with cable construction, protection concept, or certified schedule.', 'glands-and-cable-entries'),
    phase6Question('q-gland-03', 'What should be recorded for an entry finding', ['A one-word defect note stating that the entry requires general maintenance', 'Asset identifier, entry location, gland type, specific defect (e.g. damaged seal or loose locknut), and required corrective action', 'Only the name and shift schedule of the technician who performed the walk-around', 'An informal verbal request to procurement to order spare cable glands'], 1, 'A defensible entry finding records asset ID, entry location, gland type, precise defect condition, and clear corrective action.', 'glands-and-cable-entries', 'finding'),
    phase6Question('q-gland-04', 'What can a damaged cable sheath affect', ['It only affects the outer cosmetic appearance of the cable run on the tray', 'It changes the instrument signal calibration from 4-20 mA to 0-10 Volts', 'It compromises gland sealing, exposes armor to corrosion, and can allow gas or moisture migration into the enclosure', 'It has no safety impact if the internal conductors remain insulated and operational'], 2, 'Damaged outer sheath impairs environmental sealing, exposes armour to corrosion, and can allow gas migration along cable interstices.', 'glands-and-cable-entries'),
    phase6Question('q-gland-05', 'What should an unused opening have', ['No closure, provided the surrounding equipment room is dry and dust-free', 'A commercial uncertified plastic transport plug installed hand-tight', 'Heavy-duty industrial sealing tape wrapped across the exterior of the hole', 'A certified stopping plug of the correct thread form, matching material, and identical protection concept'], 3, 'Unused openings must be closed with certified stopping plugs matching the enclosure thread form, material, and protection concept.', 'glands-and-cable-entries'),
    phase6Question('q-mark-01', 'What should marking review include', ['Equipment group, category, protection concept, gas/dust group, temperature class, EPL, ambient range, and certificate suffixes', 'Only the manufacturer commercial trademark and customer sales order number', 'Only the production batch serial number stamped on the terminal DIN rail', 'Only the RAL colour code of the polyester powder coating on the enclosure'], 0, 'A complete marking review evaluates equipment group, category, protection concept, gas/dust group, temperature class, EPL, ambient range, and special conditions.', 'equipment-selection-marking'),
    phase6Question('q-mark-02', 'What does an ambient restriction communicate', ['That the apparatus can be installed in any climatic zone without derating', 'That the equipment is certified only within specified temperature boundaries (e.g. -20°C to +55°C) and requires site verification', 'The personal competence level required of the installing electrical contractor', 'The calendar date by which internal electronic components must be recalibrated'], 1, 'Ambient temperature markings (such as -20°C to +55°C) define certified operating boundaries that must encompass site climatic extremes.', 'equipment-selection-marking'),
    phase6Question('q-mark-03', 'What is a special condition for use', ['A manufacturer marketing recommendation that is optional for the installer', 'An informal design note that has no bearing on explosion safety certification', 'A mandatory certified constraint indicated by an "X" suffix that must be implemented in selection or installation', 'A substitute document that replaces the need for an official certificate of conformity'], 2, 'An "X" certificate suffix denotes specific conditions of use that are mandatory for safe installation and operation.', 'equipment-selection-marking'),
    phase6Question('q-mark-04', 'What should happen when marking is illegible', ['Copy the certification string from an adjacent equipment label of similar dimensions', 'Estimate the temperature class and gas group based on typical plant standards', 'Polish the rating plate with an abrasive pad until any remaining metal shines', 'Hold acceptance, control the asset status, and establish traceable identification from purchase records or manufacturer archives'], 3, 'Illegible marking creates an evidence deficit; acceptance must be held until identity and certification are traceably established.', 'equipment-selection-marking', 'finding'),
  ] },
  { id: 'findings-and-inspection', title: 'Findings and EX008 inspection', level: 'Advanced', description: 'Turn observations into clear findings and apply inspection thinking.', lessonIds: ['ex008-inspection', 'marking-findings-and-is-calculations'], questions: [
    phase6Question('q-find-01', 'What is the difference between an observation and a conclusion', ['An observation records objective physical facts found during inspection; a conclusion evaluates those facts against standard requirements', 'An observation and an engineering conclusion represent identical inspection statements', 'An engineering conclusion is an unverified opinion that requires no reference to standards', 'An observation is an informal verbal comment that is never entered into inspection databases'], 0, 'Observations describe verified physical facts, whereas conclusions evaluate those facts against standards and engineering criteria.', 'ex008-inspection', 'finding'),
    phase6Question('q-find-02', 'Which finding is most actionable', ['Cable gland on motor termination box appears somewhat loose', 'Asset M-22, east entry: M25 Ex d gland has 2 mm gap between seal and cable bedding; isolate and replace with correct size seal', 'Junction box wiring seems generally acceptable for continued operation', 'Inspection item flagged for review whenever maintenance technicians have available time'], 1, 'It specifies the exact asset, entry location, measured physical defect, and clear corrective action.', 'marking-findings-and-is-calculations', 'finding'),
    phase6Question('q-find-03', 'What should a finding include for closure', ['Deleting the non-conformity ticket from the computerized maintenance management system', 'An informal verbal comment that someone attended to the equipment on night shift', 'Traceable evidence, verification sign-off by competent personnel, and closeout records demonstrating compliant restoration', 'Re-tagging the equipment under a new asset number to reset the open defect history'], 2, 'Finding closure requires traceable physical evidence and competent verification that the non-conformity was corrected in compliance with standards.', 'ex008-inspection', 'finding'),
    phase6Question('q-find-04', 'Why classify inspection access and limitations', ['Because noting access restrictions eliminates the need to compile hazardous area inspection records', 'Because inaccessible equipment is automatically deemed compliant under IEC 60079-17', 'Because recording a physical barrier transfers legal liability to the equipment manufacturer', 'Because defining access limits clearly distinguishes verified items from uninspected components requiring follow-up'], 3, 'Recording access limitations prevents overclaiming inspection coverage and identifies components that remain unverified.', 'ex008-inspection'),
    phase6Question('q-find-05', "During an inspection of an energized Ex d flameproof junction box in a Zone 1 area, an inspector discovers that two adjacent cover bolts are missing, leaving a visible 1.0 mm gap between the flange faces. What is the immediate required action under IEC 60079-17", ["Log the finding as a routine defect and schedule replacement bolts for the next planned plant turnaround", "Immediately arrange for safe electrical isolation of the circuit, maintain safe control, and notify operations because explosion containment is compromised", "Inject high-temperature silicone RTV sealant into the flange gap and allow the junction box to remain energized", "Tighten the remaining bolts beyond their certified torque rating to pull the flange surfaces together"], 1, "defects that directly compromise the explosion protection concept—such as missing Ex d cover fasteners causing an open flamepath gap—represent an active ignition risk in a hazardous zone. The equipment must be safely isolated immediately before permanent repairs are performed.", 'ex008-inspection', 'finding'),
    phase6Question('q-find-08', 'What should happen when an inspection level is uncertain', ['Sign off the asset as passing a Visual inspection without further verification', 'Default to the least time-consuming inspection grade to maintain scheduled completion rates', 'Omit the inspection grade from the maintenance log to avoid procedural audits', 'Consult the hazardous area inspection plan, determine the required grade (Visual, Close, or Detailed), and seek competent guidance'], 3, 'Inspection grade (Visual, Close, or Detailed) must be determined from the approved inspection plan and applicable standards.', 'ex008-inspection'),
    phase6Question('q-find-09', 'Why separate immediate control from permanent correction', ['An immediate safety risk must be isolated or controlled at once, while permanent engineering repairs require approved parts and methods', 'Separating steps creates administrative delay so that equipment can run through the production shift', 'Applying a temporary fix removes legal obligation to carry out a certified permanent repair', 'Temporary controls make it unnecessary to document the original non-conformity in the asset register'], 0, 'Immediate controls make the condition safe, while permanent repairs require approved parts, procedures, and competent verification.', 'ex008-inspection', 'finding'),
  ] },
  { id: 'phase6-integrated-review', title: 'Phase 6 integrated review', level: 'Advanced', description: 'Integrate Ex d/e/i/p/t, glands, marking, findings, and calculations.', lessonIds: ['ex-d-flameproof', 'ex-e-increased-safety', 'ex-i-intrinsic-safety', 'ex-t-dust-protection', 'ex-p-pressurization', 'marking-findings-and-is-calculations'], questions: [
    phase6Question('q-int6-01', 'Which evidence should be connected before accepting equipment', ['Only confirming that the purchase requisition had executive management sign-off', 'Only verifying that the shipping container arrived without external transit denting', 'Area classification, environmental conditions, certificate schedule, marking, and physical installation compliance', 'Only confirming that the external enclosure was wiped clean of dust before handover'], 2, 'Defensible acceptance connects hazardous area classification, certificate schedule, marking, and verified field installation.', 'marking-findings-and-is-calculations'),
    phase6Question('q-int6-02', 'Which protection concept is especially a complete-circuit decision', ['Ex d flameproof enclosure containment', 'Ex t dust ignition protection by enclosure', 'Ex ec increased safety non-sparking equipment', 'Ex i intrinsic safety, requiring analysis of barrier, cable, and field device entity parameters as an integrated circuit'], 3, 'Intrinsic safety is a system concept requiring verification of the combined barrier, cable, and field device electrical parameters.', 'ex-i-intrinsic-safety'),
    phase6Question('q-int6-03', 'Which issue is common to several protection concepts', ['Uncontrolled physical modification or non-compliant parts substitution can invalidate certified explosion protection', 'External enclosure paint colour dictates the auto-ignition temperature classification', 'Passing an educational quiz authorises field personnel to perform mechanical alterations', 'Historical maintenance logs can be discarded once new equipment is commissioned'], 0, 'Uncontrolled modification or non-certified parts substitution undermines the fundamental protection basis across all Ex concepts.', 'marking-findings-and-is-calculations'),
    phase6Question('q-int6-04', 'What is the best response to incomplete evidence across a review', ['Interpolate missing parameters by adopting generic industrial assumptions', 'Maintain safe control, record the exact technical discrepancy, and escalate for formal engineering resolution', 'Accept the equipment on the basis that the latest installed apparatus must be compliant', 'Delete the conflicting document from the drawing register to align project records'], 1, 'Maintaining safe control and documenting the discrepancy is the only defensible response when technical evidence is incomplete.', 'marking-findings-and-is-calculations', 'finding'),
    phase6Question('q-int6-05', 'What does a worked calculation need', ['Only an unsubstantiated numeric result rounded to the nearest integer', 'Theoretical values derived without referencing verified equipment certificates', 'Transparent inputs, units, engineering formulas, stated assumptions, and verified certificate parameters', 'A fabricated certification number inserted to satisfy documentation templates'], 2, 'Transparent arithmetic requires explicit input values, verified units, standard formulas, and clear technical assumptions.', 'marking-findings-and-is-calculations', 'calculation'),
    phase6Question('q-int6-06', 'Why should gland findings identify the entry position', ['Because specifying entry position automatically updates the site CAD piping drawings', 'Because entry location alters the certified gas group rating of the gland', 'Because recording position proves the cable gland was installed by an accredited contractor', 'Because clear spatial identification ensures maintenance personnel locate the exact non-conforming entry on multi-entry enclosures'], 3, 'Exact entry coordinates on multi-entry enclosures ensure maintenance personnel rectify the specific defective component without ambiguity.', 'glands-and-cable-entries', 'finding'),
    phase6Question('q-int6-07', 'What can a dust deposit near a hot surface indicate', ['A condition requiring immediate thermal, layer depth, housekeeping, and auto-ignition temperature evaluation', 'A benign operational condition proving that natural ventilation is preventing dust cloud formation', 'Proof that internal positive pressure is operating effectively under Ex p standards', 'A demonstration that the equipment surface temperature has dropped below ambient levels'], 0, 'Dust accumulation on warm surfaces presents thermal insulation and smouldering risks requiring immediate assessment.', 'ex-t-dust-protection'),
    phase6Question('q-int6-08', 'What should an Ex p alarm bypass trigger', ['A routine automatic timer reset in the programmable logic controller', 'Immediate safety control, plant risk evaluation, and formal escalation to senior engineering authority', 'Installing an additional cable gland on the bottom enclosure gland plate', 'An automatic extension of the periodic inspection interval under IEC 60079-17'], 1, 'Bypassing an Ex p alarm or trip removes essential explosion protection and requires immediate safe control and escalation.', 'ex-p-pressurization', 'finding'),

    phase6Question('q-int6-10', 'What makes an integrated decision defensible', ['Copying generic boilerplate compliance text without reference to physical site conditions', 'Relying on verbal assurances of safety without documented inspection evidence', 'Stating that the installation appears visually satisfactory without checking engineering drawings', 'Traceable evidence connecting area classification, certification, installation condition, standards, and competent ownership'], 3, 'A defensible decision links classified area requirements, verified certification, installed field conditions, standards, and clear ownership.', 'marking-findings-and-is-calculations'),
  ] },
]

const focusedPhase6Quizzes: Quiz[] = [
  { id: 'ex001-foundations-bank', title: 'EX001 foundations question bank', level: 'Beginner', description: 'Build foundational reasoning about atmospheres, ignition, zones, groups, temperature, EPL, and evidence.', lessonIds: ['ex001-foundations', 'hazardous-areas', 'gas-vapour-mist-dust', 'zones-and-epl'], questions: [
    phase6Question('q-ex001-01', "Under the explosion triangle principle, which three conditions must coincide simultaneously for an explosion to occur in a hazardous area", ["A flammable substance in concentration between LEL and UEL, atmospheric oxygen (or oxidizer), and an ignition source with adequate energy or temperature", "A high-voltage circuit, an ingress protection deficit below IP65, and an ambient relative humidity exceeding 90%", "A secondary grade release, an Ex d flameproof enclosure, and a certified M20 barrier gland", "An electrical equipment protection level of Gc, an unarmoured multicore cable, and an ambient temperature below -20°C"], 0, "An explosion requires fuel (gas, vapour, mist, or dust) within its flammable limits, an oxidizer (typically atmospheric air), and an ignition source with energy exceeding MIE or temperature exceeding AIT.", "ex001-foundations"),
    phase6Question('q-ex001-02', "How does ventilation effectiveness influence hazardous area classification under IEC 60079-10-1", ["It eliminates the need for certified Ex equipment by converting any Zone 1 location directly into an unclassified safe area", "It controls the dispersion and dilution of releases, where high ventilation degree and good availability can reduce zone extent or downgrade zone severity", "It permits standard general-purpose plastic junction boxes to be installed inside Zone 0 vessels", "It modifies the intrinsic gas properties by increasing the Minimum Experimental Safe Gap (MESG) of released hydrocarbons"], 1, "Under IEC 60079-10-1, ventilation degree (High, Medium, Low) and availability (Good, Fair, Poor) govern release dilution, determining zone type, persistence, and boundary dimensions.", "ex001-foundations"),
    phase6Question('q-ex001-03', "What does a hazardous area \"Zone\" technically define under IEC 60079-10-1 and IEC 60079-10-2", ["The certified explosion protection concept (such as Ex d, Ex e, or Ex i) incorporated into field equipment", "The statutory qualification and competency tier of electrical personnel permitted to work on the plant", "A classification of a location based on the frequency of occurrence and duration of an explosive atmosphere", "The mechanical impact withstand capability and ingress protection rating of field enclosures"], 2, "Zones (0, 1, 2 for gases/vapours; 20, 21, 22 for combustible dusts) classify locations based on the likelihood and duration of an explosive atmosphere being present.", "ex001-foundations"),
    phase6Question('q-ex001-04', "Which physical forms of flammable release are governed by gas-risk zones (Zone 0, Zone 1, and Zone 2)", ["Combustible fibers, flyings, and conductive carbonaceous dust layers only", "Non-flammable steam releases and inert nitrogen asphyxiation zones", "Solid particulate dust clouds and combustible sawdust deposits", "Flammable gases, flammable vapours produced by liquids, and combustible mists"], 3, "Gas zones address atmospheres containing flammable gas, vapour, or mist; combustible dusts and ignitible flyings are classified under Zones 20, 21, and 22.", "ex001-foundations"),
    phase6Question('q-ex001-05', "Which combustible dust zone applies to a location where an explosive dust cloud is present continuously, frequently, or for long periods", ["Zone 20 (typically found inside dust containment vessels, silos, hoppers, and ducting)", "Zone 21 (locations where a dust cloud is likely to occur occasionally during normal operations)", "Zone 22 (locations where a dust cloud is not likely in normal operation and persists for a short duration only)", "Zone 2 (locations where an explosive gas atmosphere is not likely in normal operation)"], 0, "Zone 20 is the dust hazard zone where combustible dust clouds are present continuously, for long periods, or frequently (such as inside mills, hoppers, or transfer chutes).", "ex001-foundations"),
    phase6Question('q-ex001-06', "What is the technical basis for categorizing gases and vapours into Groups IIA, IIB, and IIC under IEC 60079-0", ["The mechanical tensile strength of enclosure metal and resistance to environmental atmospheric corrosion", "The Maximum Experimental Safe Gap (MESG) for flame propagation and the Minimum Igniting Current (MIC) ratio", "The electrical supply voltage, power factor, and short-circuit fault current of the distribution grid", "The statutory inspection frequency required by the national health and safety regulator"], 1, "Equipment Group II gases are categorized into IIA (least severe, e.g. propane), IIB (intermediate, e.g. ethylene), and IIC (most severe, e.g. hydrogen/acetylene) based on MESG and MIC ratio.", "ex001-foundations"),
    phase6Question('q-ex001-07', "What does an electrical equipment temperature class (T1 through T6) define", ["The minimum ambient temperature in which the certified equipment can safely start up without internal heaters", "The statutory training accreditation level achieved by the installation and maintenance team", "The maximum surface temperature that any part of the equipment can reach under specified operating conditions", "The thermal conductivity rating of the external powder-coated paint finish"], 2, "Temperature classes (T1: 450°C down to T6: 85°C) define the maximum permitted surface temperature of equipment relative to 40°C reference ambient, ensuring it remains below the gas auto-ignition temperature (AIT).", "ex001-foundations"),
    phase6Question('q-ex001-08', "A process plant handles diethyl ether vapour, which has an auto-ignition temperature of 160°C. Under IEC 60079-14, which temperature class represents the minimum acceptable rating for electrical equipment installed in this area", ["T3, because its 200°C limit allows a 40°C thermal margin above the gas ignition point", "T4, because its 135°C maximum surface temperature is strictly below the 160°C auto-ignition temperature", "T1, because standard industrial process equipment is designed for up to 450°C", "T2, because 300°C is permitted provided the equipment is located outdoors"], 1, "the maximum surface temperature of equipment must not exceed the auto-ignition temperature of the flammable gas. Diethyl ether ignites at 160°C; T3 (200°C) and T2 (300°C) would cause ignition. Equipment must be rated at least T4 (max surface temperature 135°C), or T5 (100°C) / T6 (85°C).", "ex001-foundations"),
    phase6Question('q-ex001-09', "What is the role of an Equipment Protection Level (EPL) such as Ga, Gb, or Gc under IEC 60079-0", ["It defines equipment ignition risk capability based on its likelihood of becoming an ignition source under normal operation, expected malfunction, or rare malfunction", "It certifies that equipment has been verified by an accredited ExCB for installation in underground coal mines only", "It provides a site-wide building exemption certificate under national workplace safety legislation", "It specifies the degree of ingress protection against high-pressure water jets and solid dust particles"], 0, "EPLs assign protection capability based on ignition likelihood: Ga/Da offers very high protection (safe with rare malfunctions), Gb/Db offers high protection (safe with expected malfunctions), and Gc/Dc offers normal protection (safe in normal operation).", "ex001-foundations"),
    phase6Question('q-ex001-10', "During initial selection review for a hydrogen compressor shelter classified as Zone 1, an engineer specifies an Ex db IIB T4 Gb motor. Why is this selection technically non-compliant under IEC 60079-14", ["Because an Ex db flameproof motor is legally restricted to Zone 2 installations", "Because hydrogen requires a minimum temperature class of T6 under all circumstances", "Because EPL Gb equipment cannot be installed in a Zone 1 classified location", "Because hydrogen is a Group IIC gas, and Group IIB certified equipment is not permitted in Group IIC atmospheres"], 3, "equipment gas grouping must correspond to the gas hazard. Hydrogen belongs to Group IIC. While equipment certified for Group IIC is permitted in Group IIA and IIB, equipment certified only for Group IIB is not certified to contain or quench IIC flame propagation (MESG < 0.5 mm).", "ex001-foundations"),
    phase6Question('q-ex001-11', "How can an engineering process change (such as modifying operating pressure or solvent composition) affect hazardous area safety", ["It automatically extends the statutory periodic inspection interval from three years to six years", "It converts all installed increased safety (Ex e) equipment into flameproof (Ex d) equipment", "It can alter release rates, flash points, ignition temperatures, or dispersion profiles, potentially invalidating the classification schedule", "It eliminates the need to maintain hazardous area verification dossiers on site"], 2, "Process alterations (flow rate, pressure, temperature, solvent substitution) alter the source and grade of release, affecting zone extent, gas group, and temperature class requirements.", "ex001-foundations"),
    phase6Question('q-ex001-12', "Why do combustible dust hazards require distinct technical evaluation compared to gas hazards", ["Because combustible dusts cannot ignite from electrostatic discharges or mechanical sparks", "Because dust atmospheres never require enclosure ingress protection or certified seals", "Because dust particles disperse instantaneously and cannot form concentrated explosive mixtures", "Because dusts form both explosive clouds and insulating layers that increase surface temperatures and smoulder"], 3, "Dusts behave differently from gases: they settle into layers that insulate equipment, lowering thermal dissipation, and can be disturbed into explosive clouds with distinct minimum ignition energy (MIE) and ignition temperatures.", "gas-vapour-mist-dust"),
    phase6Question('q-ex001-13', "Which phenomenon represents a credible potential ignition source in an industrial hazardous area", ["Hot equipment surfaces, electrical switching arcs, electrostatic discharges, and mechanically generated impact sparks", "Low-voltage digital communication signals operating below 1.2 V and 10 mA in non-inductive circuits", "Standard factory-applied anti-corrosion epoxy powder coating on cast aluminum junction boxes", "Filtered instrument air flowing through non-conductive polyurethane tubing at ambient temperature"], 0, "Credible ignition sources identified in standards include hot surfaces, electrical arcs and sparks, electrostatic discharges, friction/impact sparks, lightning, electromagnetic waves, and chemical reactions.", "ex001-foundations"),
    phase6Question('q-ex001-14', "During a site walkdown, an inspector finds an unrecorded manual sampling valve handling liquid propane installed 1.5 m outside the boundary of an outdoor Zone 2 classification area. Standard industrial lighting is installed 2 m from the valve. What is the required technical response", ["Accept the installation without review if the sampling valve is fitted with a threaded pipe plug and remains normally closed", "Immediately treat the valve as an unassessed release source, hold operations, and require a formal classification review under Management of Change", "Rely on open-air natural dilution to dissipate potential leaks before flammable concentrations reach the adjacent lighting fixture", "Re-classify the unrecorded sampling point as a secondary grade release of negligible extent without updating the area classification drawing"], 1, "Under IEC 60079-10-1, any point capable of releasing flammable liquid or gas is a potential source of release that generates a hazardous zone. An unrecorded valve located outside the classified zone exposes adjacent uncertified electrical apparatus to ignition risk. The condition must be held safe and reviewed under formal engineering MOC.", "ex001-foundations", "finding"),
    phase6Question('q-ex001-15', "Which statement accurately describes the regulatory meaning of an Ex equipment certificate and marking", ["It authorizes energization in any hazardous location without checking external installation conditions", "It certifies that the installing electrician has achieved statutory competency under national laws", "It confirms that the equipment design conformed to referenced standards under test conditions, but field installation compliance must still be verified", "It guarantees that the internal electrical components will never require maintenance or periodic inspection"], 2, "An Ex certificate confirms compliance of the product design and manufacture; safe operation depends on correct field selection, erection (IEC 60079-14), and ongoing inspection (IEC 60079-17).", "ex001-foundations", "boundary"),
    phase6Question('q-ex001-16', "An Ex eb junction box with standard nameplate marking (no ambient range indicated) is installed on an unshaded outdoor compressor skid where local ambient summer temperatures reach +48°C. What is the compliance status of this installation under IEC 60079-0 and IEC 60079-14", ["Compliant, because standard Ex equipment certification inherently covers ambient temperatures up to +50°C", "Non-compliant, because unmarked equipment is certified only for -20°C to +40°C; operation at +48°C invalidates the certificate basis of safety", "Compliant, provided the internal terminal blocks operate below 50% of their maximum rated continuous current", "Compliant, because ambient temperature limits apply only to heat-generating rotating machines and luminaires, not static junction boxes"], 1, "the standard certified ambient temperature range is -20°C to +40°C unless specially marked (e.g. Ta -20°C to +55°C). Operating unmarked equipment in a +48°C ambient violates certification limits, risking insulation thermal degradation and exceeding certified surface temperatures.", "ex001-foundations"),
    phase6Question('q-ex001-17', "When evaluating gas groups under IEC 60079-0, how does Group IIC compare to Group IIA and IIB", ["Group IIC encompasses gases with the smallest experimental safe gaps and lowest ignition energies (e.g. hydrogen and acetylene)", "Group IIC is restricted exclusively to methane atmospheres found in underground coal mines", "Group IIC equipment can only be installed in non-hazardous unclassified plant environments", "Group IIC requires lower mechanical impact resistance than Group IIA enclosures"], 0, "Group IIC represents the most volatile gas group with tightest flame transmission MESG (< 0.5 mm) and lowest MIE; equipment marked IIC is suitable for IIA and IIB, but not vice-versa.", "ex001-foundations"),
    phase6Question('q-ex001-19', "What is the required action when equipment nameplate markings are missing the gas group or temperature class", ["Assume Group IIA and T1 as default baseline values and proceed with commissioning", "Paint a provisional T4 rating on the enclosure door and schedule inspection next year", "Pause acceptance, maintain safe isolation, and obtain verified certificate documentation from the manufacturer", "Declassify the surrounding process area to Zone 2 to eliminate the marking requirement"], 2, "Missing gas group or temperature class constitutes a safety-critical documentation defect; equipment cannot be energized until authentic certificate evidence is verified.", "ex001-foundations", "finding"),
    phase6Question('q-ex001-20', "Why is using compressed air to blow settled combustible dust off equipment prohibited in hazardous areas", ["Because compressed air increases the ambient humidity, making the dust stick permanently", "Because compressed air can cause pneumatic cavitation inside sealed electrical enclosures", "Because blowing dust reduces the surface temperature of equipment, violating thermal stability rules", "Because blowing creates an airborne dust cloud in the explosive concentration range and generates electrostatic charges"], 3, "Dislodging dust layers with compressed air disperses particles into an explosive cloud and generates electrostatic charge, creating an immediate explosion hazard; vacuuming or wet cleaning is required.", "gas-vapour-mist-dust"),
    phase6Question('q-ex001-21', "What is the standard reference ambient temperature range for certified Ex equipment unless marked otherwise on the nameplate", ["-20°C to +40°C under IEC 60079-0", "0°C to +100°C for indoor industrial installations", "-50°C to +80°C for all Group II hazardous locations", "-10°C to +30°C for offshore petroleum facilities"], 0, "Under IEC 60079-0, the standard reference ambient temperature range is -20°C to +40°C. If equipment is designed for a different range (e.g. -40°C to +60°C), it must be explicitly marked.", "ex001-foundations"),
    phase6Question('q-ex001-22', "How does an Equipment Protection Level (EPL) relate to a Hazardous Area Zone", ["An EPL is an alternative European term for an equipment IP ingress protection rating", "A Zone defines the environmental likelihood of an explosive atmosphere, while an EPL defines the equipment’s inherent ignition prevention capability", "A Zone is assigned to personnel based on competency, whereas an EPL is assigned to companies", "An EPL Ga piece of equipment can only be operated when the process plant is completely shut down"], 1, "Zones classify the environment (frequency/duration of flammable atmosphere), while EPLs classify equipment risk (likelihood of becoming an ignition source); Zone 0 matches Ga, Zone 1 matches Gb, Zone 2 matches Gc.", "zones-and-epl"),
    phase6Question('q-ex001-23', "What does an \"X\" suffix at the end of an Ex certificate number signify (e.g. IECEx BAS 21.0042X)", ["The certificate has been cancelled by the certification body due to non-compliance", "The equipment is an incomplete Ex component that cannot be installed independently", "Specific conditions of use apply that must be satisfied for safe installation and operation", "The equipment has undergone extended fire-proof testing under high-pressure steam"], 2, "An \"X\" suffix indicates Specific Conditions of Use (such as special cable types, electrostatic precautions, or external fusing) detailed in the certificate schedule that must be complied with.", "equipment-selection-marking"),
    phase6Question('q-ex001-24', "During an initial inspection of a newly painted Ex d flameproof control station, an inspector observes that the flanged cover was painted while open, leaving a 120 μm layer of cured industrial epoxy on the flamepath mating surfaces. What is the technical evaluation under IEC 60079-14 and IEC 60079-17", ["Acceptable, because epoxy primer provides certified corrosion protection to the machined surfaces", "Acceptable, provided the enclosure cover fasteners are torqued 20% above nominal rating to compress the paint film", "A non-conformity; flamepaths must not be painted because paint compromises flamepath gap dimensions and can burn through during an internal explosion", "Acceptable, provided a non-hardening grease is applied over the cured epoxy before closing the cover"], 2, "painting flamepath joint surfaces is prohibited. Cured paint introduces an uncontrolled gap dimension, prevents true metal-to-metal flame quenching, and can burn or decompose during an explosion, allowing flame transmission to the outside atmosphere.", "ex001-foundations", "finding"),
    phase6Question('q-ex001-26', "Under IEC 60079-14, how is the maximum permissible surface temperature determined for equipment exposed to combustible dust clouds and layers", ["By adopting the highest ambient temperature recorded at the facility during the summer season", "By taking the lower of: two-thirds of the dust cloud ignition temperature (2/3 Tcloud) or 75 K below the 5 mm dust layer ignition temperature (T5mm - 75°C)", "By fixing the surface limit to exactly 100°C for all dust groups (IIIA, IIIB, and IIIC)", "By matching the auto-ignition temperature of methane gas (537°C)"], 1, "Under IEC 60079-14, maximum surface temperature for dust must not exceed 2/3 of Tcloud (in °C) and must be at least 75 K below the ignition temperature of a 5 mm dust layer (T5mm - 75°C), choosing the lower value.", "gas-vapour-mist-dust"),
    phase6Question('q-ex001-27', "Why is it critical to establish which specific edition of IEC 60079 standards governs an installation", ["Because older standards editions permitted electrical equipment to be installed without earthing", "Because every new edition automatically revokes all existing plant operating licenses worldwide", "Because technical requirements, test methods, and protection concepts evolve across editions, defining the legal design basis of the plant", "Because newer standards editions eliminate the need for detailed periodic inspections"], 2, "The applicable standard edition defines the design and installation rules in force at the time of construction, governing baseline compliance and grandfathering boundaries under IEC 60079-14/17.", "ex001-foundations", "boundary"),
    phase6Question('q-ex001-30', "An engineering contractor evaluates an intrinsically safe 4-20 mA loop but lacks cable manufacturer datasheets for an existing 450 m cable. The contractor assumes a default capacitance of 80 pF/m and signs off the loop. What is the technical issue under IEC 60079-14", ["Default cable parameters cannot be assumed; cable electrical parameters (Cc and Lc or Lc/Rc) must be verified from manufacturer data or measured directly", "Default values are permitted, but only if the overall cable length is under 500 metres", "Intrinsically safe loops do not require cable capacitance verification if the barrier provides galvanic isolation", "Cable parameters only require verification if the field instrument contains internal inductors"], 0, "cable electrical parameters (capacitance and inductance, or L/R ratio) must be determined from the cable manufacturer's specification or through direct measurement. Unvalidated assumptions can lead to exceeding barrier Co or Lo limits, creating a spark ignition hazard.", "ex001-foundations", "boundary"),
    phase6Question('q-ex001-31', "What is the primary engineering purpose of a Hazardous Area Classification Drawing", ["To serve as an architectural marketing plan for prospective industrial plant investors", "To replace the need for equipment nameplate marking verification during installation", "To provide a spatial plan defining zone types, extents, gas/dust groups, and temperature classes for safe equipment selection", "To specify the exact torque settings for enclosure cover bolts across all process skids"], 2, "Hazardous area classification drawings illustrate the spatial boundaries of Zone 0/1/2 or 20/21/22, release sources, gas/dust groups, and T-classes, establishing the technical basis for equipment selection.", "ex001-foundations"),
    phase6Question('q-ex001-32', "Why does IEC 60079-10-1 require identifying the release grade (continuous, primary, or secondary) for flammable substances", ["Because release grade determines the electrical power consumption of downstream process pumps", "Because secondary releases are legally exempt from hazardous area classification rules", "Because continuous releases can only occur inside pressurized control rooms", "Because the release grade directly dictates the expected frequency and duration of an explosive atmosphere, determining the zone"], 3, "Release grades define likelihood: continuous release generally leads to Zone 0, primary release to Zone 1, and secondary release to Zone 2 (subject to ventilation effectiveness).", "ex001-foundations"),
    phase6Question('q-ex001-33', "An instrument control unit nameplate displays the marking Ex db eb [ia Ga] IIC T4 Gb. How should an installation inspector interpret the physical arrangement and rating of this equipment", ["The unit is certified exclusively as an intrinsically safe sensor that must be physically installed inside Zone 0", "The main enclosure is flameproof (Ex db) with an increased safety (Ex eb) terminal chamber, containing associated apparatus with IS circuits capable of connecting into Zone 0", "The enclosure is pressurised (Ex p) with dual containment and flameproof internal relays", "The apparatus is non-sparking (Ex ec) with intrinsically safe galvanic barriers suitable only for Zone 2"], 1, "composite marking describes combined protection concepts: Ex db designates the flameproof body, Ex eb designates the increased safety terminal box, and square brackets [ia Ga] indicate associated apparatus providing intrinsically safe circuits extending into Zone 0, with an overall equipment rating of EPL Gb (Zone 1).", "ex001-foundations", "finding"),
    phase6Question('q-ex001-34', "How does high process fluid temperature in a vessel affect the hazardous area ignition risk of released vapours", ["It eliminates the flammable range by driving away all atmospheric oxygen molecules", "It raises the liquid temperature above its flash point, drastically increasing vapour pressure and the rate of explosive atmosphere formation", "It lowers the electrical resistance of the plant earthing grid, causing ground fault trips", "It changes the gas group classification of the fluid from Group IIB to Group IIA"], 1, "Liquids handled at or above their flash point release substantial flammable vapours; elevated process temperatures increase release rates and expand the physical extent of the hazardous zone.", "ex001-foundations"),
    phase6Question('q-ex001-35', "An intrinsically safe loop calculation evaluates a barrier with Co = 100 nF. The transmitter has Ci = 20 nF and is connected via 300 m of instrument cable specified at 150 pF/m. What is the total circuit capacitance and its compliance status under IEC 60079-14", ["Total capacitance is 65 nF (20 nF + 45 nF), which is <= Co (100 nF) and therefore compliant", "Total capacitance is 470 nF (20 nF + 450 nF), which exceeds Co (100 nF) and is non-compliant", "Total capacitance is 20.045 nF, because cable picofarads are negligible compared to nanofarads", "Total capacitance is 45 nF, because transmitter internal capacitance Ci is ignored in simple loops"], 0, "Cable capacitance equals 300 m * 150 pF/m = 45,000 pF = 45 nF. Total lumped capacitance Ci + Cc = 20 nF + 45 nF = 65 nF..3, since 65 nF <= Co (100 nF), the circuit satisfies the permitted capacitance limit.", "ex001-foundations", "calculation"),
  ] },
  { id: 'ex007-focused-bank', title: 'EX007 visual and close inspection bank', level: 'Intermediate', description: 'Practise visible installation and inspection observations without confusing observation with approval.', lessonIds: ['ex007-installation-practice', 'ex008-inspection', 'glands-and-cable-entries'], questions: [
    phase6Question('q-ex007-11', "Under IEC 60079-17, what is the defined physical limitation of a Visual Inspection grade", ["It requires opening the flameproof enclosure to measure internal creepage distances", "It involves applying high-voltage insulation resistance testing to all internal conductors", "It is conducted using specialized torque wrenches to verify cover bolt clamping force", "It identifies defects without opening enclosures or using access equipment or tools, leaving internal conditions unverified"], 3, "A Visual inspection identifies defects visible to the eye without access equipment or tools, and cannot verify internal components, terminal torque, or flamepath gaps.", "ex007-installation-practice", "finding"),
    phase6Question('q-ex007-12', "What distinguishes a Close Inspection from a Visual Inspection under IEC 60079-17", ["A Close inspection requires access equipment (e.g. steps) and tools to inspect visible aspects closely (such as bolt tightness), but does not require opening enclosures", "A Close inspection mandates completely disassembling internal spark-gap assemblies under microscope", "A Close inspection is performed exclusively from the central plant control room via SCADA telemetry", "A Close inspection eliminates the need to record asset tag numbers or location data"], 0, "Close inspection encompasses visual inspection aspects plus defects detectable using access equipment and tools (e.g. checking bolt tightness or gland locknuts) without opening the enclosure.", "ex007-installation-practice"),
    phase6Question('q-ex007-13', "During an initial inspection, an inspector finds an Ex d motor with an illegible, corroded nameplate. What is the correct action", ["Stamp a new brass nameplate with estimated data and attach it using standard self-tapping screws", "Record a non-conformity noting the asset tag and location, maintain safe control, and trace the certified data via plant records or manufacturer serial number", "Assume the motor is rated Ex d IIC T4 because other motors in the same compressor room share that rating", "Declassify the motor enclosure as non-hazardous equipment to avoid recording a defect"], 1, "An illegible nameplate prevents verifying EPL, gas group, and T-class; the asset identity must be documented and verified against controlled engineering dossiers.", "ex007-installation-practice", "finding"),
    phase6Question('q-ex007-14', "Why does physical damage to an Ex cable outer sheath (such as gouging or splitting) represent a safety non-conformity under IEC 60079-14", ["Because outer sheath damage instantly voids the software warranty of the programmable logic controller", "Because any sheath defect converts an intrinsically safe circuit into a non-intrinsically safe power circuit", "Because sheath damage compromises environmental sealing, exposes armour to corrosion, and can allow gas or moisture migration along the cable bedding", "Because cables in hazardous areas are pressurized with inert gas that leaks when the sheath is cut"], 2, "Cable sheath integrity is essential to prevent moisture ingress, corrosion of armour/braid, mechanical degradation, and flammable gas migration into connected enclosures.", "ex007-installation-practice"),
    phase6Question('q-ex007-15', "What is the required response when an inspector discovers a loose, corroded external equipotential bonding conductor on a certified Ex enclosure", ["Ignore the connection because internal protective earthing (PE) makes external bonding redundant", "Apply silicone sealant over the loose lug and sign off the inspection as fully compliant", "Remove the bonding conductor permanently to eliminate earth loop circulating currents", "Record a non-conformity, isolate if sparking is observed, clean mating faces, restore correct fastener torque, and verify continuity (< 1 ohm)"], 3, "Equipotential bonding prevents dangerous potential differences and sparks between conductive parts; loose/corroded bonds must be documented, refurbished, and continuity-tested.", "ex007-installation-practice", "finding"),
    phase6Question('q-ex007-16', "Which observable condition indicates an unauthorized field modification that invalidates equipment Ex certification", ["An uncertified drilled entry hole or unapproved internal component not documented in the certificate schedule", "A stainless steel asset identification tag affixed to the mounting frame using approved rivets", "A factory-supplied breather drain installed in the bottom entry following manufacturer instructions", "A calibration label affixed to the external housing indicating the latest inspection date"], 0, "Drilling unapproved holes, altering flamepaths, or installing non-certified internal components modifies the certified design and invalidates equipment certification.", "ex007-installation-practice", "finding"),
    phase6Question('q-ex007-17', "Why must severe surface corrosion on an Ex d flameproof enclosure be evaluated as a potential explosion safety hazard", ["Because external rust causes the internal operating voltage to drop below nominal limits", "Because corrosion can pit machined flamepath joint surfaces, reduce enclosure wall thickness, and weaken high-tensile cover fasteners", "Because rust alters the chemical composition of flammable hydrocarbons, lowering their auto-ignition temperature", "Because corrosion instantly voids the personnel competency certificate of the maintenance technician"], 1, "Corrosion on Ex d enclosures can pit machined flamepath mating faces, compromise wall structural containment, and seize or weaken fasteners needed to withstand internal explosion pressures.", "ex007-installation-practice", "finding"),
    phase6Question('q-ex007-18', "What is the compliant method for closing an unused cable entry in an Ex d flameproof enclosure under IEC 60079-14", ["Fitting a standard commercial nylon blind grommet sealed with weatherproofing silicone", "Inserting a general industrial brass bolt wrapped with PTFE thread sealant tape", "Installing a certified Ex d stopping plug that matches the thread form and metric pitch with minimum 5 engaged threads", "Packing the empty threaded entry hole with fire-resistant ceramic wool insulation"], 2, "Unused Ex d entries must be closed with certified Ex d stopping plugs of matching thread form and size, achieving at least 5 full threads of engagement (or 8 mm thread length).", "glands-and-cable-entries", "finding"),
    phase6Question('q-ex007-19', "What wording should an inspector avoid when recording a technical non-conformity in an inspection report", ["Precise equipment tag numbers and physical coordinates within the plant structure", "Specific standard clause references such as specific standard clauses", "Observable physical measurements such as measured flamepath gap clearance in millimeters", "Vague subjective assertions such as \"looks unsafe\" or \"seems fine\" without verifiable evidence and standards references"], 3, "Inspection findings must be factual, objective, and defensible, citing specific observed conditions, measurements, and relevant standard requirements rather than unsubstantiated subjective opinions.", "ex007-installation-practice", "finding"),
    phase6Question('q-ex007-20', "Under what circumstance is immediate escalation and safe isolation required during an Ex inspection", ["When an active ignition risk is identified, such as an open flamepath gap, energization of damaged Ex d gear, or sparking terminals", "When minor cosmetic paint flaking is noted on an external non-flamepath mounting bracket", "When an inspection tag has been filled out in blue ink instead of black ballpoint pen", "When a stainless steel nameplate shows minor atmospheric rain water spotting"], 0, "Immediate isolation and escalation are mandatory when an imminent ignition risk exists—such as compromised flameproof enclosures, loose arcing connections, or pressurized enclosure loss in hazardous zones.", "ex007-installation-practice", "finding"),
    phase6Question('q-ex007-21', "What must an inspector verify when examining an IP66 Ex e junction box installed in an exposed outdoor washdown area", ["That the enclosure cover bolts have been greased with conductive copper-slip anti-seize paste", "That cover gaskets are intact and seated, entry threads have approved sealing washers, and breathers maintain IP66", "That the junction box is connected to an uncertified domestic compressed air line for purging", "That all internal electrical terminals have been removed and replaced with soldered wire joints"], 1, "Ex e enclosures rely on continuous ingress protection (minimum IP54, often IP66 outdoors) to exclude moisture and contaminants; gaskets, sealing washers, and certified drain plugs must be verified.", "glands-and-cable-entries"),
    phase6Question('q-ex007-22', "Why must ambient temperature conditions be recorded during hazardous area installation inspections", ["To verify whether maintenance technicians are entitled to outdoor adverse weather allowance", "To calculate the exact thermodynamic efficiency of three-phase squirrel cage induction motors", "To confirm the installation operates within certified equipment ambient limits (e.g. -20°C to +40°C or marked special range)", "To determine whether the hazardous area classification can be downgraded from Zone 1 to Zone 2"], 2, "Ex certification is valid only within the specified ambient range (standard: -20°C to +40°C; special: e.g. -40°C to +60°C); extreme site temperatures can compromise material properties and temperature class.", "ex007-installation-practice"),
    phase6Question('q-ex007-23', "What can an inspector verify regarding enclosure fasteners during a Close Inspection under IEC 60079-17", ["The internal metallurgical grain structure and carbon content of each fastener via spectral analysis", "The tensile rupture yield point under destructive high-pressure hydrostatic testing", "The date on which the bolts were manufactured and shipped from the fastener distribution warehouse", "Presence, correct type, lack of visible damage or corrosion, and tightness using hand tools without opening the enclosure"], 3, "A Close inspection verifies fastener presence, correct grade/type (e.g. A2-70, 8.8), lack of missing bolts, and tightness using hand tools without opening the enclosure.", "ex007-installation-practice", "finding"),
    phase6Question('q-ex007-24', "During a Detailed inspection of an Ex d motor, an inspector uses a 0.25 mm feeler gauge that fully penetrates a flanged flamepath joint where the maximum permitted gap is 0.15 mm. To produce defensible non-conformity evidence, how should the defect photograph be captured", ["A macro shot showing only the feeler gauge blade without any enclosure features or context", "An eye-level photograph of the motor junction box taken with the terminal cover removed", "A clear photograph showing the feeler gauge inserted with marked blade thickness visible, contextual framing showing the motor asset tag, and exact joint location", "A wide-angle photograph of the motor skid taken from outside the unit boundary fence"], 2, "inspection evidence must be objective, verifiable, and traceable. A defensible defect photo must clearly display the measurement tool/gauge marking, the exact physical defect location, and the equipment asset tag for unambiguous attribution.", "ex007-installation-practice", "finding"),
    phase6Question('q-ex007-25', "What evidence is required before formally closing an Ex installation non-conformity report", ["A verbal assurance from the construction contractor that the item was resolved during shift handover", "Documented corrective evidence, re-inspection verification by a competent person, and updated maintenance records", "Deleting the open non-conformity ticket from the computerized maintenance database", "Repainting the exterior enclosure surface with grey industrial primer paint"], 1, "Closing non-conformities requires physical rectification, documented verification by competent personnel under applicable standards, and updating the hazardous area verification dossier.", "ex007-installation-practice", "finding"),
    phase6Question('q-ex007-26', "Why must cable glands and accessories be verified against manufacturer installation instructions", ["Because manufacturer instructions specify the purchase price and supplier warranty terms", "Because manufacturer instructions replace the need to comply with IEC 60079-14 standards", "Because incorrect assembly, missing armour cones, wrong torque, or inverted seals defeat certified sealing and retention", "Because manufacturer instructions indicate the statutory tax classification of industrial electrical equipment"], 2, "Cable glands achieve certified protection (clamping, earth continuity, ingress protection, flameproof seal) only when assembled strictly in accordance with manufacturer instructions and torque specifications.", "ex007-installation-practice"),
    phase6Question('q-ex007-27', "What key parameters must be confirmed when inspecting an armoured cable gland termination under IEC 60079-14", ["Only that the external brass shroud is clean and polished with brass cleaner", "Only that the cable core insulation colors match international harmonized standards", "Only that the cable gland body is marked with the equipment manufacturer’s corporate logo", "Correct thread engagement, locknut tightness, IP sealing washer, armour clamping integrity, and earth tag bonding"], 3, "Armoured cable gland verification requires checking thread engagement, locknut security, IP washer, correct armour cone clamping for mechanical retention and earth fault return, and outer sheath seal.", "ex007-installation-practice"),
    phase6Question('q-ex007-28', "Why must unused entries in an Ex e increased safety enclosure never be left open or fitted with non-certified plugs", ["Because open or uncertified entries destroy the minimum IP54 enclosure rating, admitting dust, moisture, and foreign bodies that cause tracking", "Because open entries allow natural air circulation that cools internal electrical terminals below 0°C", "Because uncertified plugs alter the three-phase AC supply frequency from 50 Hz to 60 Hz", "Because open entries reduce the mechanical strength of the concrete mounting structure"], 0, "Ex e relies on preventing sparks, arcs, and excessive temperatures; open entries allow moisture and conductive dust ingress, causing insulation breakdown and electrical tracking arcs.", "ex007-installation-practice", "finding"),
  ] },
  { id: 'ex008-focused-bank', title: 'EX008 detailed inspection bank', level: 'Advanced', description: 'Practise detailed inspection boundaries, findings, glands, terminals, and evidence-led decisions.', lessonIds: ['ex008-inspection', 'ex-d-flameproof', 'ex-e-increased-safety', 'glands-and-cable-entries'], questions: [
    phase6Question('q-ex008-11', "Under IEC 60079-17, what safety controls must be verified before opening an energized Ex d or Ex e enclosure in a hazardous area", ["Confirming that the technician holds an advanced university degree in electrical engineering", "Positive electrical isolation and lockout/tagout, verification of zero energy, gas-free atmosphere testing, and an approved permit-to-work", "Ensuring that the enclosure cover bolts are loosened while the circuit remains on full electrical load", "Applying a dry powder fire extinguisher directly into the open enclosure cavity"], 1, "Opening Ex equipment in hazardous areas requires safe electrical isolation (LOTO), proving dead, atmospheric gas testing, and authorized permit-to-work procedures to prevent ignition.", "ex008-inspection", "boundary"),
    phase6Question('q-ex008-12', "During a detailed inspection of an Ex d flameproof enclosure, an inspector finds a longitudinal scratch across the full width of a flanged flamepath. Why is this critical", ["Because the scratch alters the external paint finish color and violates site cosmetic guidelines", "Because any scratch converts the flameproof enclosure into an increased safety (Ex e) junction box", "Because a continuous scratch across the joint width can allow escaping burning gas to ignite the external atmosphere", "Because scratches cause internal vacuum that prevents the enclosure cover from ever being removed"], 2, "Flanged flamepaths quench escaping explosion flames through narrow gaps; a continuous scratch spanning the joint width creates a channel that bypasses flame quenching, causing external ignition.", "ex008-inspection", "finding"),
    phase6Question('q-ex008-13', "Why is replacing an Ex d enclosure cover bolt with an unknown commercial bolt of unidentified property class a dangerous violation", ["Because bolts from non-approved suppliers will cause galvanic corrosion within 24 hours", "Because metric bolts cannot be screwed into imperial threaded enclosure holes", "Because commercial bolts alter the certified temperature class marking of the enclosure", "Because Ex d fasteners must withstand internal explosion pressure without yielding; incorrect property class (e.g. 4.6 vs 8.8) can cause cover failure"], 3, "Ex d enclosures develop significant internal explosion pressures (typically 8–15 bar); fasteners of specified property class (e.g. 8.8 or A2-70) are engineered to prevent flamepath gap expansion or shearing.", "ex008-inspection", "finding"),
    phase6Question('q-ex008-14', "Why does IEC 60079-14 strictly prohibit applying setting sealants, adhesives, or non-approved gaskets to Ex d flamepath joints", ["Because setting sealants and adhesives can separate joint surfaces or form rigid barriers that increase flamepath gap dimensions under explosion pressure", "Because sealants convert the flameproof enclosure into an oil-immersed (Ex o) electrical device", "Because sealants react chemically with copper conductors, causing short circuits inside the box", "Because applying non-metallic grease reduces the external ingress protection rating from IP66 to IP20"], 0, "Flamepaths must not be modified with setting compounds, glue, or unauthorized gaskets; only approved non-setting, non-metallic anti-corrosion grease (or certified elastomeric O-rings in designed grooves) is permitted.", "ex008-inspection", "finding"),
    phase6Question('q-ex008-15', "During a Detailed Inspection of an Ex eb junction box under IEC 60079-17, which internal conditions must be verified", ["That the internal wiring is wrapped in commercial PVC insulation tape without terminal blocks", "Terminal tightness, creepage and clearance distances, absence of damaged conductor strands, correct conductor ferrule crimping, and no overheating signs", "That the terminal rail has been sprayed with flammable WD-40 moisture repellent liquid", "That all terminal screws have been fully loosened to prevent thermal expansion stress"], 1, "Detailed Ex eb inspection requires examining terminals for correct torque, proper conductor preparation (e.g. ferrules on stranded wire), verified creepage and clearance distances, and absence of thermal discoloration.", "ex008-inspection"),
    phase6Question('q-ex008-16', "What is the technical hazard of cut or broken conductor strands at an Ex e terminal connection", ["It automatically changes the gas group rating of the junction box from Group IIB to Group IIA", "It causes the circuit breaker to trip instantly on residual current earth leakage", "It reduces effective conductor cross-section, causing localized resistive overheating, and stray strands can violate creepage and clearance distances", "It causes the ambient temperature outside the enclosure to drop below -20°C"], 2, "Damaged strands reduce current-carrying capacity, generating dangerous local hot spots, while stray loose strands reduce clearance to adjacent poles or earth, risking electrical flashover.", "ex008-inspection", "finding"),
    phase6Question('q-ex008-17', "What non-conformity does excessive stripped conductor copper extending outside an Ex e terminal clamp represent", ["An unauthorized field increase in the equipment Equipment Protection Level (EPL)", "A compliant earthing practice that provides supplemental capacitive discharge paths", "A minor aesthetic variance that requires no recording in the hazardous area dossier", "A reduction in minimum creepage and clearance distances through air, creating an electric flashover or arcing risk"], 3, "Exposed bare conductor outside terminal clamps reduces clearance and creepage distances below certified minimums specified in IEC 60079-7, increasing the risk of spark generation or short-circuit flashover.", "ex008-inspection", "finding"),
    phase6Question('q-ex008-18', "What is the function of terminal partition plates (separators) installed between terminal blocks in an Ex e enclosure", ["To maintain mandatory creepage and clearance distances between adjacent circuits or between power and intrinsically safe wiring", "To conduct heat from terminal clamps directly into the external cast aluminum enclosure walls", "To serve as certified electrical fuses that melt during moderate overcurrent conditions", "To absorb moisture from internal enclosure air through chemical desiccant action"], 0, "Partition plates maintain certified creepage and clearance distances between adjacent terminals..2, an insulating partition plate extending within 1.5 mm of enclosure walls is the accepted alternative to maintaining a 50 mm physical clearance in air between intrinsically safe and non-intrinsically safe connection facilities.", "ex008-inspection"),
    phase6Question('q-ex008-19', "If combustible dust contamination is found inside an Ex t dust-ignition protected enclosure during inspection, what must be done", ["Blow the dust out into the room using a compressed air lance while the equipment is energized", "De-energize, record the finding, investigate enclosure/gland ingress failure, clean using approved methods, and restore certified sealing", "Ignore the dust deposit if it is less than 50 mm thick and covers less than half of the terminals", "Spray water inside the enclosure to convert the combustible dust into non-flammable sludge"], 1, "Dust inside an Ex t enclosure proves that ingress protection (IP6X) has failed; equipment must be de-energized, inspected for gasket or gland defects, cleaned safely, and restored to compliant IP integrity.", "ex008-inspection", "finding"),
    phase6Question('q-ex008-20', "Why is it critical to verify that cable diameter matches the certified clamping range of an Ex cable gland", ["Because an undersized cable will cause the cable gland outer body to crack during tightening", "Because an oversized cable improves ingress protection beyond the certified IP68 standard", "Because an undersized cable prevents effective elastomeric seal compression and mechanical pull-out clamping, compromising explosion containment and IP", "Because matching cable diameter is required only for aesthetic alignment in cable tray ladders"], 2, "Gland elastomeric sealing rings and armour clamping cones function only across their certified cable diameter range; an undersized cable leaves gaps permitting gas/dust ingress and inadequate cable retention.", "glands-and-cable-entries"),
    phase6Question('q-ex008-21', "Which cable construction characteristics must be verified before selecting or inspecting a barrier cable gland under IEC 60079-14", ["Only the overall cable length and the purchase order requisition number", "Only the manufacturer’s commercial brand name and outer jacket colour", "Only the nominal AC current carrying capacity under continuous load", "Bedding diameter, circularity, presence of non-compacted fillers, and whether gas can migrate through the cable interstices"], 3, "Barrier glands (compound-filled) are selected based on cable bedding dimensions, non-circular geometry, or hygroscopic/non-compacted fillers that could allow explosive gas migration along the internal cores.", "glands-and-cable-entries"),
    phase6Question('q-ex008-22', "How does a compound barrier cable gland prevent gas migration into an unclassified or remote area", ["It seals each individual insulated conductor within a curing setting compound, blocking gas flow through internal cable interstices", "It introduces a continuous supply of pressurized nitrogen into the cable armour layer", "It burns off flammable vapours at the gland entry through a controlled internal pilot flame", "It restricts electrical current flow to less than 1 milliampere under hazardous conditions"], 0, "A barrier gland separates and embeds all cable conductors in an epoxy/resin compound, sealing the interstices between individual cores and preventing flammable gas or flame transmission through the cable interior.", "glands-and-cable-entries"),
    phase6Question('q-ex008-23', "When an Ex cable gland certificate displays an \"X\" suffix, what is the inspector obligated to verify", ["Confirm that the cable gland has been approved for use without an external earth tag", "Consult the certificate schedule to verify that specific conditions (such as external clamping or fixed installation) are met", "Assume the gland is uncertified and remove it immediately without checking documents", "Verify that the cable gland is painted red to denote hazardous area application"], 1, "The \"X\" suffix denotes Specific Conditions of Use (e.g. requiring additional external cable clamping within 300 mm to prevent pull-out) that must be satisfied in the physical installation.", "glands-and-cable-entries", "boundary"),
    phase6Question('q-ex008-24', "What does a \"U\" suffix on a certificate number signify (e.g. Sira 18ATEX1234U)", ["The equipment is an universal replacement suitable for any zone without limitation", "The certificate has been upgraded to include combustible dust Group IIIC ratings", "The item is an Ex Component (such as a terminal or empty enclosure) requiring incorporation into a fully certified equipment assembly", "The product is certified for use exclusively by undergraduate engineering apprentices"], 2, "A \"U\" certificate denotes an Ex Component that is not permitted to be installed independently; it must be incorporated into complete equipment that receives full Ex equipment certification.", "equipment-selection-marking", "boundary"),
    phase6Question('q-ex008-25', "During an EX008 Detailed Inspection, the certificate for an Ex d control station cannot be located in the site dossier. What is the correct action", ["Accept the installation if the external nameplate looks authentic and shows an Ex symbol", "Delete the control station asset tag from the inspection register to clear open audit defects", "Fabricate a replacement certificate number using standard industry numbering formats", "Record a non-conformity noting an evidence gap, maintain safe control, and obtain the certified schedule from the manufacturer or ExCB"], 3, "Equipment cannot be validated without its certificate schedule (especially for special conditions X); an evidence gap must be logged, safe control maintained, and controlled documentation retrieved.", "ex008-inspection", "finding"),
    phase6Question('q-ex008-26', "In a professional inspection finding, what is the definition and role of an \"Observation\"", ["An objective, factual statement describing the physical as-found condition, measurements, and verifiable evidence without conjecture", "A personal intuition or feeling regarding whether the plant manager cares about safety", "A binding legal judgment imposing statutory fines on the equipment installation contractor", "A financial estimate of how much the replacement electrical hardware will cost"], 0, "Observations must be objective, factual descriptions of what was seen, measured, or tested (e.g. \"Flamepath gap measured at 0.25 mm with calibrated feeler gauge, exceeding 0.15 mm maximum\").", "ex008-inspection", "finding"),
    phase6Question('q-ex008-27', "How does an inspector distinguish an \"observation\" from a \"non-conformity\"", ["An observation is written in pencil, whereas a non-conformity is typed in ink", "An observation describes the physical fact, while a non-conformity establishes that the fact violates a specific requirement in standards or design", "An observation applies to Zone 2 equipment, while a non-conformity applies to Zone 0 equipment", "An observation is raised by the technician, while a non-conformity can only be raised by lawyers"], 1, "An observation records the factual reality; comparing that fact against standards, certification, or design reveals whether a non-conformity exists (e.g. \"Fact: bolt missing\" -> \"Non-conformity: relevant standard clause\").", "ex008-inspection", "finding"),
    phase6Question('q-ex008-28', "When physical access limitations prevent completing all checklist items for an Ex asset during inspection, what must be recorded", ["Record the asset as 100% compliant and fully inspected to prevent maintenance backlog", "Omit the asset from the inspection schedule and claim it was decommissioned", "Explicitly document the access restriction, what portions were inspected, and what items remain unverified", "Guess the internal condition of the uninspected equipment based on adjacent similar units"], 2, "Inspection records must never overclaim coverage; recording specific limitations ensures safety integrity by identifying exactly which items require follow-up when access becomes available.", "ex008-inspection", "finding"),
    phase6Question('q-ex008-29', "Under what condition must an inspector immediately stop an Ex detailed inspection", ["When the inspection checklist contains more than ten technical line items", "When the ambient air temperature drops below +15°C in an outdoor plant area", "When the inspector encounters a metric fastener that requires a metric socket wrench", "When safe working conditions are breached, hot work hazards arise, or continuing would violate safe isolation procedures"], 3, "Inspection work must immediately halt if safety boundaries, electrical isolation, explosive gas absence, structural access, or environmental controls are compromised.", "ex008-inspection", "boundary"),
    phase6Question('q-ex008-30', "Which of the following field inspection log entries represents an actionable and defensible Detailed inspection finding under IEC 60079-17", ["Asset JB-042 (Zone 1, Gas Group IIB): Detailed inspection found flanged flamepath gap measured at 0.25 mm with calibrated feeler gauge (max certified gap 0.15 mm). Non-conformity per IEC 60079-17 Table 1 Item B1. Priority 1; isolate circuit; assigned to Electrical Team.", "Enclosure in Zone 1 inspected; cover flamepath appears to have some clearance issues that should be monitored during routine rounds.", "Detailed inspection completed for compressor junction box; equipment verified as generally compliant with visual standards.", "Flameproof box inspected; technician recommends replacing entire assembly due to general age and service conditions."], 0, "an actionable finding requires traceable asset identification, zone classification, inspection grade, objective physical measurements compared against certified limits, standard reference, risk priority, and assigned ownership.", "ex008-inspection", "finding"),
    phase6Question('q-ex008-31', "If internal wiring in an Ex e motor terminal box differs from the certified manufacturer connection diagram, what is the required response", ["Accept the wiring if the motor runs in the correct rotational direction without vibration", "Document the deviation, hold acceptance, and route through technical engineering review under Management of Change", "Redraw the manufacturer diagram informally on site to match the as-found terminal connections", "Disconnect the motor earth connection to prevent differential trip currents"], 1, "Internal wiring variances can alter terminal loading, temperature rise ($t_E$), or clearance distances; deviations must be held and evaluated through formal engineering MOC.", "ex008-inspection", "finding"),
    phase6Question('q-ex008-32', "Why does IEC 60079-19 require repairs and overhauls of Ex equipment to be conducted only by competent certified facilities", ["Because certified repair facilities receive commercial discounts from equipment manufacturers", "Because standard industrial repair workshops are legally prohibited from purchasing metric screws", "Because improper machining, rewinding, or parts replacement can alter flamepaths, temperature classes, or insulation integrity, causing explosions", "Because certified repair facilities guarantee that repaired equipment will never require future inspection"], 2, "Repairing Ex apparatus involves safety-critical tolerances (flamepath dimensions, stator winding insulation, thermal dissipation); IEC 60079-19 sets strict rules to preserve the certificate basis of safety.", "ex008-inspection", "boundary"),
    phase6Question('q-ex008-33', "What constitutes a technically sound escalation note when an inspection non-conformity cannot be resolved on shift", ["Writing \"temporary defect, please resolve when convenient\" in the general maintenance comments", "Promising that the non-conformity will be reviewed during the next major plant turnaround in four years", "Omitting the asset tag number to prevent premature alarm among operations personnel", "Stating the exact asset tag, observed condition, potential explosion hazard, immediate controls applied, assigned owner, and required engineering resolution"], 3, "Escalation notes must clearly define the asset, observed defect, explosion protection implication, immediate safe isolation/mitigation in place, and the specific engineering action needed.", "ex008-inspection", "finding"),
    phase6Question('q-ex008-34', "Why should inspection findings be analyzed against historical records in the hazardous area verification dossier", ["To detect recurring failure trends, premature component degradation, or systemic maintenance issues across equipment populations", "To automatically cancel the statutory requirement to conduct future periodic inspections", "To identify which electrical technicians can be penalized for reporting equipment defects", "To prove that equipment installed over ten years ago is legally exempt from standards compliance"], 0, "Analyzing historical records under IEC 60079-17 reveals degradation rates, environmental vulnerabilities, and chronic defect trends, informing inspection interval adjustments.", "ex008-inspection"),
    phase6Question('q-ex008-35', "What verification steps must be completed following a corrective repair on an Ex d flameproof enclosure before re-energization", ["Verifying that the repair vendor’s invoice was approved by the finance department", "Conducting a Detailed inspection verifying flamepath gap tolerances, fastener torque, stopping plug integrity, and updating dossier records", "Inspecting only the external paint finish to verify colour uniformity with adjacent plant items", "Energizing the enclosure immediately and checking whether the exterior surface feels warm"], 1, "Following repair, an IEC 60079-17 Detailed inspection must confirm that flamepath dimensions meet certificate schedules, correct fasteners are torqued, and repair documentation is filed in the dossier.", "ex008-inspection", "finding"),
    phase6Question('q-ex008-36', "What is the operational consequence when an inspection report records an \"inspection limitation\" on safety-critical Ex equipment", ["The equipment is automatically certified as permanently compliant without further inspection", "The hazardous area classification surrounding the equipment is automatically derated", "The uninspected items remain open safety risks that must be scheduled for verification under approved access controls", "The inspection team’s competency credentials are automatically suspended by the certification body"], 2, "An inspection limitation marks unverified boundaries; the uninspected features represent potential hazards that require planned follow-up when plant conditions or access allow.", "ex008-inspection", "boundary"),
  ] },
]

